function curataNumeLuna(str) {
  if (!str) return "";
  let curat = str.toString().trim();
  curat = curat.replace(/^luna\s+/i, "").replace(/^month\s+/i, "").trim();
  if (!curat) return "";
  return curat.charAt(0).toUpperCase() + curat.slice(1).toLowerCase();
}

function populeazaSelectorLuni() {
  let selLuna = document.getElementById('filtruLunaIncasari');
  let selLunaOrar = document.getElementById('filtruLunaOrar');
  let selLunaFisa = document.getElementById('filtruLunaFisa');

  let luniSet = new Set();
  const luniRoNume = ["Ianuarie", "Februarie", "Martie", "Aprilie", "Mai", "Iunie", "Iulie", "August", "Septembrie", "Octombrie", "Noiembrie", "Decembrie"];

  (DB.incasari || []).forEach(i => {
    if (i && i.luna && i.luna.trim() !== "-" && i.luna.trim() !== "") {
      let n = curataNumeLuna(i.luna);
      if (n) luniSet.add(n);
    }
  });

  (DB.prezente || []).forEach(p => {
    if (p && p.data && p.data.indexOf('.') !== -1) {
      let parts = p.data.split('.');
      if (parts.length === 3) {
        let m = parseInt(parts[1], 10);
        if (m >= 1 && m <= 12) {
          luniSet.add(luniRoNume[m - 1]);
        }
      }
    }
  });

  function calculeazaScorLuna(str) {
    if (!str) return 0;
    let s = str.toLowerCase().trim();
    let anGasit = 0;
    let anMatch = s.match(/\b(20\d\d)\b/);
    if (anMatch) anGasit = parseInt(anMatch[1], 10);
    
    let lunaIdx = -1;
    for (let idx = 0; idx < luniRoNume.length; idx++) {
      if (s.indexOf(luniRoNume[idx].toLowerCase()) !== -1) {
        lunaIdx = idx;
        break;
      }
    }
    return (anGasit || 2026) * 100 + (lunaIdx !== -1 ? lunaIdx : 0);
  }

  let luniArray = Array.from(luniSet);
  luniArray.sort((a, b) => calculeazaScorLuna(b) - calculeazaScorLuna(a));

  [selLuna, selLunaOrar, selLunaFisa].forEach(sel => {
    if (!sel) return;
    let valAnterioara = sel.value;
    sel.innerHTML = `<option value="">${t('allMonths')}</option>`;
    luniArray.forEach(luna => {
      let opt = document.createElement('option');
      opt.value = luna;
      opt.innerText = traduceValoare(luna);
      sel.appendChild(opt);
    });
    if (valAnterioara) sel.value = valAnterioara;
  });
}

function comutaTab(tabId, titlu, btn, tipTab, tabIdx) {
  tipTabCurent = tipTab;
  // Etichetă simplă pe pagină pentru stilurile Orarului (în loc de body:has(#tabOrar.active), costisitor la derulare)
  document.body.classList.toggle('pe-orar', tabId === 'tabOrar');
  // Tab-urile trecute pe stilul nou (al Orarului): fundalul cu pete de lumină și cardurile de sticlă
  document.body.classList.toggle('stil-nou', ['tabOrar', 'tabProgramari', 'tabIncasari', 'tabFisa'].includes(tabId));

  const bottomNav = document.getElementById('bottomNav');
  if (bottomNav) {
    bottomNav.style.display = 'flex';
    bottomNav.classList.remove('nav-compact');
  }

  document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));
  document.querySelectorAll('#bottomNav button').forEach(el => el.classList.remove('active'));
  let target = document.getElementById(tabId);
  if (target) target.classList.add('active');
  if (btn) btn.classList.add('active');

  if (typeof tabIdx === 'number') {
    animaPilaMercur(tabIdx);
  }

  // Confirmări: aplicația lăsată deschisă peste pragul de vineri seara / miezul nopții trece întâi pe săptămâna de acum
  if (tipTab === 'prog') gestioneazaRevenireForeground();

  if (tipTab === 'incasari') {
    reseteazaDateIncasariAzi();
    // Desenată cât tab-ul era ascuns, eticheta „față de …” n-avea lățime: acum se potrivește (și „De reînnoit” e la zi)
    requestAnimationFrame(filtreazaIstoricIncasariInstant);
  }

  // Titlul vine mereu din tabsOrder în limba curentă (butoanele din bara de jos trimit titlul scris în română)
  const tabInfo = tabsOrder.find(tb => tb.id === tabId);
  if (tabInfo) titlu = currentLang === 'en' ? tabInfo.titleEn : tabInfo.titleRo;
  actualizeazaHeaderVisual(tipTab, titlu);

  let detOrar = document.getElementById('detailsIstoricOrar');
  if (detOrar) detOrar.open = false;

  let detInc = document.getElementById('detailsIstoricIncasari');
  if (detInc) detInc.open = false;

  let detAdaugFisa = document.getElementById('detailsDetailsAdaugareClienta');
  if (detAdaugFisa) detAdaugFisa.open = false;

  let detEditFisa = document.getElementById('detailsEditareFisa');
  if (detEditFisa) detEditFisa.open = false;

  let detIstFisa = document.getElementById('detailsIstoricFisa');
  if (detIstFisa) detIstFisa.open = false;

  if (tipTab === 'orar') {
    ajusteazaNumeZile(document.getElementById('dayButtonsContainer'));
    autoScrollLaOraCurenta();
  } else {
    window.scrollTo({ top: 0, behavior: 'auto' });
  }
}

// Iconițele din antetul orei: ceas (ora deschisă, apăsarea o blochează) și lacăt (ora blocată)
const ICON_CEAS_ORA = '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>';
const ICON_LACAT_ORA = '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>';

// Eticheta din antetul orei: „3 libere”, „1 liber”, „Complet”
function textLocuriLibere(libere) {
  if (libere <= 0) return tr('Complet', 'Full');
  return libere === 1 ? tr('1 loc liber', '1 spot free') : `${libere} ${tr('locuri libere', 'spots free')}`;
}

// Titlul mare al Orarului: ziua aleasă și, pentru săptămâna curentă / viitoare, cifrele zilei
function actualizeazaTitluOrar(cifre) {
  let elData = document.getElementById('orarDataLunga');
  let elCifre = document.getElementById('orarCifre');
  let elTitlu = document.getElementById('orarTitluText');
  if (elTitlu) elTitlu.textContent = tr('Orar', 'Schedule');
  let z = getZileConfig().find(x => x.cheie === ziCurentaCheie);
  if (elData && z) {
    let luna = z.dataDate.toLocaleString(currentLang === 'en' ? 'en-US' : 'ro', { month: 'long' });
    elData.textContent = `${traduceValoare(z.nume)}, ${z.dataDate.getDate()} ${luna}`;
  }
  if (!elCifre) return;
  elCifre.hidden = !cifre;
  // Filtrul ține doar de ziua pe care a fost ales; altă zi / săptămână trecută / grup golit între timp: toată ziua
  const ziFiltru = `${getSaptamanaCheie()}_${ziCurentaCheie}`;
  if (filtruOrar && (!cifre || filtruOrarZi !== ziFiltru || !cifre[filtruOrar])) aplicaFiltruOrar(null);
  if (!cifre) return;
  const cifra = (grup, nr, text, culoare) => `<button type="button" class="orar-cifra${culoare ? ' orar-cifra-' + culoare : ''}${filtruOrar === grup ? ' activ' : ''}" data-filtru="${grup}"${nr ? '' : ' disabled'} onclick="filtreazaOrar('${grup}')"><b>${nr}</b><span>${text}</span></button>`;
  elCifre.innerHTML = cifra('programati', cifre.programati, tr('programați', 'booked'), '')
    + cifra('prezenti', cifre.prezenti, tr('prezenți', 'present'), 'verde')
    + cifra('libere', cifre.libere, tr('libere', 'free'), 'accent');
}

// Filtrele Orarului (cifrele zilei): Programați = locurile ocupate, Prezenți = cei bifați, Libere = locurile goale.
// Doar ascund rânduri (CSS, după data-stare); a doua atingere arată iar toată ziua. Orele blocate nu intră în cifre, deci nici în filtre.
let filtruOrar = null, filtruOrarZi = '';
function filtreazaOrar(grup) {
  aplicaFiltruOrar(filtruOrar === grup ? null : grup);
  // Derulat mai jos de prima oră: lista filtrată se vede de la început, sub bara zilelor și filtre
  const cont = document.getElementById('sloturiContainer');
  const sus = cont ? cont.getBoundingClientRect().top + window.scrollY - getTopOffsetSubZile() : 0;
  if (cont && window.scrollY > sus) window.scrollTo({ top: sus, behavior: 'smooth' });
}
function aplicaFiltruOrar(grup) {
  filtruOrar = grup;
  filtruOrarZi = grup ? `${getSaptamanaCheie()}_${ziCurentaCheie}` : '';
  const cont = document.getElementById('sloturiContainer');
  if (cont) cont.dataset.filtru = grup || '';
  document.querySelectorAll('#orarCifre .orar-cifra').forEach(b => b.classList.toggle('activ', b.dataset.filtru === grup));
}

// Cercul unui loc ocupat: inițialele, cu poza de profil peste ele când clientul are cont și poză
// (Storage public „avatars/<id cont>/avatar.webp”). Pozele care lipsesc nu se mai cer până la reîncărcare.
var avatareLipsa = new Set();

function avatarSlotHtml(clienta) {
  let initiale = (clienta.nume || '').trim().split(/\s+/).map(c => c[0] || '').join('').slice(0, 2).toUpperCase();
  let id = clienta.authUserId;
  if (!id || avatareLipsa.has(id) || typeof supabaseClient === 'undefined') return escAttr(initiale);
  let url = supabaseClient.storage.from('avatars').getPublicUrl(`${id}/avatar.webp`).data.publicUrl;
  return `${escAttr(initiale)}<img src="${escAttr(url)}" alt="" loading="lazy" onload="this.parentNode.classList.add('are-poza')" onerror="avatarLipsa('${escAttr(id)}', this)">`;
}

function avatarLipsa(id, img) {
  avatareLipsa.add(id);
  img.remove();
}

// Fișa pe scurt (apăsare pe inițialele / poza clientului): doar citește datele, nu schimbă nimic.
// Cifrele și butoanele depind de pagină: slotul din Orar = ședința, 'istoric' = prezențele, 'incasari' = abonamentul și plata;
// fără pagină (Confirmări, care își adaugă blocul ei) rămâne varianta de bază.
function arataFisaScurta(idClient, zi, ora, slotIdx, pagina) {
  const c = (DB.clienti || []).find(x => x && x.id === idClient);
  if (!c) return;
  const dinSlot = !!(zi && ora && typeof slotIdx === 'number');
  inchideFisaScurta();
  const numeMic = c.nume.trim().toLowerCase();
  const cheieData = d => {
    const m = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec((d || '').trim());
    return m ? `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}` : (d || '');
  };
  const prezenteLui = (DB.prezente || [])
    .filter(p => p && p.clienta && p.clienta.trim().toLowerCase() === numeMic)
    .sort((a, b) => cheieData(b.data).localeCompare(cheieData(a.data)));
  const ultima = prezenteLui[0];
  // Alerta de sănătate din fișa de obiective (ca în antetul fișei): ce are și detaliile, pe scurt
  const fisa = c.fisaInscriere || {};
  const probleme = problemeSanatate(fisa);
  // Câte un rând pe problemă, întreg (nu tăiat): ce are și detaliile scrise de client
  const alerta = probleme.length ? `<div class="fisa-scurta-alerta">${probleme.map(id => `<div>⚠ <b>${escAttr(textInscriere(ETICHETE_SCURTE_INSCRIERE[id]))}</b>${fisa[id + 'Detalii'] ? `: ${escAttr(fisa[id + 'Detalii'])}` : ''}</div>`).join('')}</div>` : '';
  const ramaseText = c.incluse > 0 ? String(c.ramase) : '–';
  const ramaseCls = c.incluse > 0 && c.ramase <= 0 ? 'rosu' : (c.incluse > 0 && c.ramase === 1 ? 'portocaliu' : '');
  const cifra = (val, eticheta, cls) => `<div><b${cls ? ` class="${cls}"` : ''}>${escAttr(String(val ?? ''))}</b><span>${eticheta}</span></div>`;
  const ramase = cifra(ramaseText, tr('Ședințe rămase', 'Sessions left'), ramaseCls);
  const abonament = cifra(numeAbonamentClienta(c.tipAbonament), tr('Abonament', 'Membership'));
  // Zile de azi până la o dată din bază (negativ = în trecut), pentru ultima prezență și expirare
  const azi0 = new Date().setHours(0, 0, 0, 0);
  const zileDeAzi = d => { const t = parseazaDataOraRo(d); return t ? Math.round((new Date(t).setHours(0, 0, 0, 0) - azi0) / 86400000) : null; };
  const inUrma = ultima ? -zileDeAzi(ultima.data) : null;
  const ultimaText = inUrma === null || isNaN(inUrma) ? (ultima ? ultima.data : '–')
    : inUrma === 0 ? tr('azi', 'today') : inUrma === 1 ? tr('ieri', 'yesterday')
    : tr(`acum ${inUrma} zile`, `${inUrma} days ago`);
  const ultimaPrezenta = cifra(ultimaText, tr('Ultima prezență', 'Last attendance'));
  // Ca în „De reînnoit”: roșu = expirat, portocaliu = expiră în cel mult 7 zile
  const zileExp = c.incluse > 0 ? zileDeAzi(c.dataExpirare) : null;
  const valabil = cifra(c.dataExpirare, tr('Valabil până la', 'Valid until'), zileExp === null ? '' : zileExp < 0 ? 'rosu' : zileExp <= 7 ? 'portocaliu' : '');
  let grila;
  if (dinSlot) {
    const antUltim = prezenteLui.find(p => p.antrenament && p.antrenament.trim() !== '-');
    grila = ramase + cifra(antUltim ? traduceValoare(antUltim.antrenament) : '–', tr('Ultimul antrenament', 'Last workout')) + ultimaPrezenta + valabil;
  } else if (pagina === 'istoric') {
    const azi = new Date();
    const lunaAsta = isoDinData(azi).slice(0, 7);
    const acum28 = isoDinData(new Date(azi.getFullYear(), azi.getMonth(), azi.getDate() - 28));
    const peSapt = Math.round(prezenteLui.filter(p => cheieData(p.data) > acum28).length / 4 * 10) / 10;
    grila = cifra(prezenteLui.filter(p => cheieData(p.data).startsWith(lunaAsta)).length, tr('Prezențe luna asta', 'Attended this month'))
      + cifra(String(peSapt).replace('.', currentLang === 'en' ? '.' : ','), tr('Pe săpt. (4 săpt.)', 'Per week (4 wks)')) + ultimaPrezenta + ramase;
  } else if (pagina === 'incasari') {
    const plata = (DB.incasari || []).filter(i => i && i.data && (i.client_id === c.id || cheieNume(i.clienta || '') === cheieNume(c.nume)))
      .sort((a, b) => cheieData(b.data).localeCompare(cheieData(a.data)))[0];
    grila = abonament + ramase + valabil
      + cifra(plata ? formateazaSuma(plata.suma) : '–', plata ? `${tr('Ultima plată', 'Last payment')} · ${escAttr(plata.data.replace(/\.\d{4}$/, ''))}` : tr('Ultima plată', 'Last payment'));
  } else grila = ramase + abonament + ultimaPrezenta + valabil;
  const buton = (id, svg, text, principal) => `<button type="button" class="fisa-scurta-actiune${principal ? ' fisa-scurta-actiune-principala' : ''}" id="${id}">${svg}${text}</button>`;
  const actiuni = pagina === 'incasari'
    ? buton('btnFisaIncaseaza', ICON_ISTORIC_PLATA, tr('Încasează', 'Collect'), true)
    : pagina === 'istoric'
      ? buton('btnFisaDoarClient', '<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>', tr('Doar acest client', 'Only this client'))
      : buton('btnAdaugaAntrenament', '<svg viewBox="0 0 24 24"><path d="M6.5 6.5v11M17.5 6.5v11M3 9.5v5M21 9.5v5M6.5 12h11"/></svg>', tr('Adaugă antrenament', 'Add workout'));

  const fundal = document.createElement('div');
  fundal.className = 'fisa-scurta-fundal';
  fundal.id = 'fisaScurtaFundal';
  const foaie = document.createElement('div');
  foaie.className = 'fisa-scurta';
  foaie.id = 'fisaScurta';
  foaie.innerHTML = `
    <div class="fisa-scurta-maner"><span></span></div>
    <div class="fisa-scurta-antet">
      <div class="slot-num">${avatarSlotHtml(c)}</div>
      <b>${escAttr(c.nume)}</b>
    </div>${alerta}
    <div class="fisa-scurta-grila">${grila}</div>
    <div class="fisa-scurta-actiuni">
      ${actiuni}
      ${dinSlot ? `<button type="button" class="fisa-scurta-actiune" id="btnRepetaSaptamanal" title="${tr('Același loc în următoarele 4 săptămâni', 'Same spot for the next 4 weeks')}"><svg viewBox="0 0 24 24"><path d="M17 2l3 3-3 3"/><path d="M4 11V9a4 4 0 0 1 4-4h12"/><path d="M7 22l-3-3 3-3"/><path d="M20 13v2a4 4 0 0 1-4 4H4"/></svg>${tr('Repetă săptămânal', 'Repeat weekly')}</button>` : ''}
      <button type="button" class="fisa-scurta-actiune${pagina === 'incasari' ? '' : ' fisa-scurta-actiune-principala'}" id="btnFisaCompleta">${tr('Fișa completă', 'Full profile')}<svg viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg></button>
    </div>`;
  if (dinSlot) foaie.querySelector('#btnRepetaSaptamanal').onclick = () => { inchideFisaScurta(); repetaSaptamanal(c, zi, ora, slotIdx); };
  const btnAntrenament = foaie.querySelector('#btnAdaugaAntrenament');
  if (btnAntrenament) btnAntrenament.onclick = () => {
    const antEl = dinSlot ? document.getElementById(`ant_${normalizeazaOraUi(ora).replace(':', '')}_${slotIdx}`) : null;
    inchideFisaScurta();
    adaugaAntrenamentPentru(c, antEl ? (antEl.dataset.valoare ?? antEl.value) : '');
  };
  if (pagina === 'incasari') foaie.querySelector('#btnFisaIncaseaza').onclick = () => { inchideFisaScurta(); deschideIncasareNoua({ nume: c.nume, tip: c.tipAbonament }); };
  if (pagina === 'istoric') foaie.querySelector('#btnFisaDoarClient').onclick = () => {
    inchideFisaScurta();
    const camp = document.getElementById('filtruClientaOrar');
    camp.value = c.nume;
    camp.dispatchEvent(new Event('input', { bubbles: true })); // filtrează lista și arată × din câmp, ca la scris
  };
  foaie.querySelector('#btnFisaCompleta').onclick = () => {
    inchideFisaScurta();
    comutaTab('tabFisa', 'Clienți', document.getElementById('navBtnFisa'), 'fisa', 2);
    deschideClientaDinLista(c.nume);
  };
  trageInJosCaSaInchizi(foaie, inchideFisaScurta); // de oriunde de pe fișă, nu doar de mâner
  adaugaFoaieJos(fundal, foaie, inchideFisaScurta);
  sincronizeazaIstoricInapoi(); // „Înapoi” de pe telefon închide fereastra
}

// Fereastra de jos creată pe loc: fundalul și fereastra alături în pagină, ca la plata nouă. Nu în fundal: când el se stinge,
// fereastra s-ar stinge cu el și și-ar pierde blurul din primul cadru (prin ea s-ar vedea pagina), ceea ce pare sacadat.
function adaugaFoaieJos(fundal, foaie, inchide) {
  fundal.onclick = inchide;
  document.body.append(fundal, foaie);
}

// Închiderea ferestrelor de jos: coboară lin de unde se află (și după ce a fost trasă cu degetul), fundalul se stinge,
// apoi `gata` o ascunde sau o șterge. Fundalul își pierde id-ul pe loc, ca o redeschidere să-și facă unul nou;
// o redeschidere în timpul coborârii o oprește cu opresteCoborarea (gata nu mai rulează).
function coboaraFereastra(foaie, fundal, gata) {
  fundal?.removeAttribute('id');
  if (fundal) fundal.style.pointerEvents = 'none';
  const v = foaie?._vitezaInchidere;
  if (foaie) foaie._vitezaInchidere = null;
  if (!foaie || foaie.hidden || !foaie.getClientRects().length || matchMedia('(prefers-reduced-motion: reduce)').matches) { fundal?.remove(); gata(); return; }
  // De unde a lăsat-o degetul, tot ca translateY: din matrix() spre translateY(%) animația nu mai rula separat de pagină
  // (cadrele așteptau după pagină, pe Orar mai ales), deci după tragere fereastra stătea o clipă și sacada
  const y = new DOMMatrix(getComputedStyle(foaie).transform).m42;
  const de = `translateY(${y}px)`;
  foaie.style.animation = 'none';
  foaie.style.pointerEvents = 'none';
  // Atingere în afară / Înapoi: aceeași curbă ca la urcare (fisaIntra), pornește repede.
  // După tragere (_vitezaInchidere, px/ms): coboară uniform cu viteza degetului (cel puțin 1,6 px/ms), ca foile native;
  // cu curba de mai sus pornea brusc și apoi se târa ultima bucată vizibilă, adică se închidea „în două etape”
  const durata = v != null
    ? { duration: Math.min(240, Math.max(80, (foaie.offsetHeight - y) / Math.max(v, 1.6))), easing: 'linear', fill: 'forwards' }
    : { duration: 260, easing: 'cubic-bezier(0.32, 0.72, 0, 1)', fill: 'forwards' };
  const a = foaie.animate([{ transform: de }, { transform: v != null ? 'translateY(100%)' : 'translateY(105%)' }], durata);
  // După tragere pornește din primul cadru deja în mișcare (altfel stătea un cadru pe loc la ridicarea degetului)
  if (v != null) a.currentTime = 16;
  // Fundalul se stinge uniform, în același timp cu fereastra (nu rămâne întunecat după ce ea a ieșit)
  fundal?.animate([{ opacity: getComputedStyle(fundal).opacity }, { opacity: 0 }], { duration: durata.duration, fill: 'forwards' });
  foaie._coborare = a;
  foaie._fundalIesire = fundal;
  a.finished.then(() => {
    foaie._coborare = foaie._fundalIesire = null;
    fundal?.remove();
    gata();
    a.cancel();
    foaie.style.pointerEvents = '';
  }).catch(() => {});
}

function opresteCoborarea(foaie) {
  if (!foaie || !foaie._coborare) return;
  foaie._coborare.cancel();
  foaie._fundalIesire?.remove();
  foaie._coborare = foaie._fundalIesire = null;
  foaie.style.pointerEvents = '';
}

// Ca foile native: se închide după o tragere lungă (`prag`) sau după una scurtă dar rapidă în jos (viteza în px/ms,
// din ultima mișcare a degetului), ca să nu revină sus și să trebuiască trasă din nou
// Viteza = pe ultimele ~100 ms ale degetului, nu pe ultima mișcare: la ridicare degetul frânează, iar fereastra ar fi
// continuat mai încet decât era trasă (o „întrerupere” la mijlocul coborârii)
function urmaresteVitezaTragere() {
  let puncte = [], v = 0;
  return {
    start(yy, tt) { puncte = [[tt, yy]]; v = 0; },
    misca(yy, tt) {
      puncte.push([tt, yy]);
      while (puncte.length > 2 && tt - puncte[0][0] > 100) puncte.shift();
      const [t0, y0] = puncte[0];
      if (tt > t0) v = (yy - y0) / (tt - t0);
    },
    // Închide și dă ferestrei viteza degetului, ca coborârea să continue cu ea (coboaraFereastra)
    inchide(dy, prag, foaie, inchide) {
      if (!(dy > prag || (dy > 12 && v > 0.35))) return false;
      foaie._vitezaInchidere = Math.max(0, v);
      inchide();
      return true;
    }
  };
}

// Fereastra de jos urmează trasă în jos și se închide (vezi urmaresteVitezaTragere).
// Cu degetul: prin touch (trageInJosDinConținut), ca plata nouă; pe telefon tragerea prin pointer rămânea o clipă în urmă.
// Cu mouse-ul: prin pointer, de pe `zona` dacă e dată (la ferestrele care derulează), altfel de oriunde; butoanele și câmpurile rămân ale lor.
// animation = 'none': animația de intrare ține transformarea ocupată și fereastra n-ar urma degetul.
function trageInJosCaSaInchizi(foaie, inchide, zona) {
  let y0 = null;
  const viteza = urmaresteVitezaTragere();
  foaie.addEventListener('pointerdown', e => {
    if (e.pointerType === 'touch' || e.target.closest('button, textarea, input, select') || (zona && !e.target.closest(zona))) return;
    y0 = e.clientY; foaie.style.animation = 'none'; foaie.style.transition = 'none';
    viteza.start(e.clientY, e.timeStamp);
    try { foaie.setPointerCapture(e.pointerId); } catch (x) {}
  });
  foaie.addEventListener('pointermove', e => {
    if (y0 === null) return;
    foaie.style.transform = `translateY(${Math.max(0, e.clientY - y0)}px)`;
    viteza.misca(e.clientY, e.timeStamp);
  });
  const gata = e => {
    if (y0 === null) return;
    const dy = e.clientY - y0;
    y0 = null;
    foaie.style.transition = '';
    if (!viteza.inchide(dy, 60, foaie, inchide)) foaie.style.transform = '';
  };
  foaie.addEventListener('pointerup', gata);
  foaie.addEventListener('pointercancel', gata);
  trageInJosDinConținut(foaie, inchide, zona);
}

// Pe telefon, de oriunde (și din conținut, ca în aplicațiile native): din `zona` mereu, din rest doar când fereastra e
// derulată sus și degetul coboară; altfel derulează normal. Prin touch, pentru că derularea ia evenimentele pointer
// (pointercancel) înainte ca fereastra să le poată urma.
function trageInJosDinConținut(foaie, inchide, zona) {
  let x0 = 0, y0 = null, trage = false, dinZona = false;
  const viteza = urmaresteVitezaTragere();
  foaie.addEventListener('touchstart', e => {
    y0 = e.touches.length === 1 ? e.touches[0].clientY : null;
    x0 = y0 === null ? 0 : e.touches[0].clientX;
    dinZona = !!(zona && e.target.closest(zona));
    trage = false;
    if (y0 !== null) viteza.start(y0, e.timeStamp);
  }, { passive: true });
  foaie.addEventListener('touchmove', e => {
    if (y0 === null) return;
    const dy = e.touches[0].clientY - y0;
    if (!trage) {
      // Doar în jos și mai mult vertical decât lateral (o glisare laterală în fereastră nu o mișcă)
      if ((!dinZona && foaie.scrollTop > 0) || dy <= 0 || Math.abs(e.touches[0].clientX - x0) > dy) { y0 = null; return; }
      trage = true;
      foaie.style.animation = 'none'; foaie.style.transition = 'none';
    }
    e.preventDefault();
    foaie.style.transform = `translateY(${Math.max(0, dy)}px)`;
    viteza.misca(e.touches[0].clientY, e.timeStamp);
  }, { passive: false });
  const gata = e => {
    if (!trage) { y0 = null; return; }
    const dy = e.changedTouches[0].clientY - y0;
    y0 = null; trage = false;
    foaie.style.transition = '';
    if (!viteza.inchide(dy, 80, foaie, inchide)) foaie.style.transform = '';
  };
  foaie.addEventListener('touchend', gata);
  foaie.addEventListener('touchcancel', gata);
}

// Cheia săptămânii (W_AAAA_LL_ZZ, lunea) la `pas` săptămâni după săptămâna afișată
function cheieSaptamanaPeste(pas) {
  const d = new Date(dataReferintaLuni.getTime());
  d.setDate(d.getDate() + 7 * pas);
  return `W_${d.getFullYear()}_${String(d.getMonth() + 1).padStart(2, '0')}_${String(d.getDate()).padStart(2, '0')}`;
}

function sloturiZi(cheie, zi) {
  return (DB.orarSloturi || []).filter(s => s && s.ziRaw && (s.ziRaw === `${cheie}_${zi}` || (zi === 'Marti' && s.ziRaw === `${cheie}_Marți`)));
}

// Programare recurentă: același client, aceeași zi, oră și loc în următoarele 4 săptămâni.
// Sare săptămânile unde locul e ocupat de altcineva sau ora e blocată; salvarea e cea obișnuită (salveazaSlotAuto)
function repetaSaptamanal(c, zi, ora, slotIdx) {
  const oraNorm = normalizeazaOraUi(ora);
  const antEl = document.getElementById(`ant_${oraNorm.replace(':', '')}_${slotIdx}`);
  const antrenament = antEl ? (antEl.dataset.valoare ?? antEl.value) : '';
  const numeZi = traduceValoare((getZileConfig().find(z => z.cheie === zi) || {}).nume || zi).toLowerCase();
  customConfirm(
    tr('Repetă săptămânal', 'Repeat weekly'),
    tr(`Programezi pe ${c.nume} ${numeZi} la ${oraNorm} și în următoarele 4 săptămâni? Săptămânile în care locul e ocupat sau ora e blocată se sar.`,
       `Book ${c.nume} on ${numeZi} at ${oraNorm} for the next 4 weeks too? Weeks where the spot is taken or the hour is blocked are skipped.`),
    () => {
      let facute = 0;
      for (let pas = 1; pas <= 4; pas++) {
        const cheie = cheieSaptamanaPeste(pas);
        const ziua = sloturiZi(cheie, zi).filter(s => normalizeazaOraUi(s.ora) === oraNorm);
        if (ziua.some(s => s.blocat)) continue;
        const loc = ziua.find(s => Number(s.slotIndex) === Number(slotIdx));
        if (loc && loc.clienta && loc.clienta.trim()) continue;
        callBackend('salveazaSlotAuto', {
          row: loc ? loc.row : null, saptamanaCheie: cheie, zi, ora: oraNorm, slotIndex: slotIdx,
          clienta: c.nume, antrenament
        }, () => {});
        facute++;
      }
      showToast(facute
        ? tr(`Programat în ${facute} din 4 săptămâni`, `Booked in ${facute} of 4 weeks`)
        : tr('Locul e ocupat în toate cele 4 săptămâni', 'The spot is taken in all 4 weeks'), facute ? 'success' : 'error');
      if (facute) setTimeout(() => incarcaBazaDateSilencios(), 1500);
    }
  );
}

// Căutare rapidă: scrii câteva litere și vezi clientul, cu programările lui din săptămâna afișată
function deschideCautareClient() {
  inchideFisaScurta();
  const fundal = document.createElement('div');
  fundal.className = 'fisa-scurta-fundal';
  fundal.id = 'fisaScurtaFundal';
  const foaie = document.createElement('div');
  foaie.className = 'fisa-scurta cautare-client';
  foaie.id = 'fisaScurta';
  foaie.innerHTML = `
    <div class="fisa-scurta-maner"><span></span></div>
    <input type="search" class="cautare-client-camp" placeholder="${tr('Caută client', 'Find client')}" autocomplete="off" enterkeyhint="search">
    <div class="cautare-client-rezultate"></div>`;
  const camp = foaie.querySelector('input');
  const rezultate = foaie.querySelector('.cautare-client-rezultate');
  const fara = s => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const cheie = getSaptamanaCheie();
  const zile = getZileConfig();
  const deseneaza = () => {
    const q = fara(camp.value.trim());
    if (!q) { rezultate.innerHTML = ''; return; }
    // Întâi cei al căror nume începe cu literele scrise, apoi prenumele / alt cuvânt, apoi restul potrivirilor
    const rang = n => n.startsWith(q) ? 0 : n.split(/[\s-]+/).some(w => w.startsWith(q)) ? 1 : n.includes(q) ? 2 : -1;
    const gasiti = (DB.clienti || [])
      .filter(c => c && c.nume && !/^(arhivat|archived)$/i.test(c.status || ''))
      .map(c => ({ c, r: rang(fara(c.nume)) }))
      .filter(x => x.r >= 0)
      .sort((a, b) => a.r - b.r || a.c.nume.localeCompare(b.c.nume, 'ro'))
      .slice(0, 6)
      .map(x => x.c);
    rezultate.innerHTML = gasiti.length ? gasiti.map(c => {
      const prog = zile.flatMap(z => sloturiZi(cheie, z.cheie)
        .filter(s => s.clienta && s.clienta.trim().toLowerCase() === c.nume.trim().toLowerCase())
        .map(s => ({ zi: z.cheie, nume: traduceValoare(z.nume), ora: normalizeazaOraUi(s.ora), idx: Number(s.slotIndex) || 0, bifat: !!s.bifat })))
        .sort((x, y) => zile.findIndex(z => z.cheie === x.zi) - zile.findIndex(z => z.cheie === y.zi) || x.ora.localeCompare(y.ora));
      return `<div class="cautare-client-rand">
        <button type="button" class="cautare-client-nume" data-id="${escAttr(c.id)}"><span class="slot-num">${avatarSlotHtml(c)}</span><b>${escAttr(c.nume)}</b></button>
        <div class="cautare-client-prog">${prog.length
          ? prog.map(p => `<button type="button" class="cautare-client-ora${p.bifat ? ' bifat' : ''}" data-zi="${p.zi}" data-ora="${p.ora}" data-idx="${p.idx}">${escAttr(p.nume.slice(0, 2))} ${p.ora}</button>`).join('')
          : `<small>${tr('Nicio programare săptămâna asta', 'No bookings this week')}</small>`}</div>
      </div>`;
    }).join('') : `<small class="cautare-client-gol">${tr('Niciun client găsit', 'No client found')}</small>`;
    rezultate.querySelectorAll('.cautare-client-nume').forEach(b => {
      b.onclick = () => {
        const c = (DB.clienti || []).find(x => x.id === b.dataset.id);
        inchideFisaScurta();
        if (!c) return;
        comutaTab('tabFisa', 'Clienți', document.getElementById('navBtnFisa'), 'fisa', 2);
        deschideClientaDinLista(c.nume);
      };
    });
    rezultate.querySelectorAll('.cautare-client-ora').forEach(b => {
      b.onclick = () => {
        inchideFisaScurta();
        schimbaZiInstant(b.dataset.zi);
        setTimeout(() => {
          if (filtruOrar) aplicaFiltruOrar(null); // un filtru activ ar putea ascunde rândul căutat
          const rand = document.getElementById(`cli_${b.dataset.ora.replace(':', '')}_${b.dataset.idx}`)?.closest('.slot-row');
          if (!rand) return;
          // Tot cardul orei (cu ora sus) sub bara zilelor și filtre; dacă așa clientul ar rămâne sub bara de jos
          // (multe locuri, el printre ultimele), pagina urcă doar cât să se vadă rândul lui întreg
          const bloc = rand.closest('.hour-block') || rand;
          let tinta = bloc.getBoundingClientRect().top + window.scrollY - getTopOffsetSubZile();
          const nav = document.getElementById('bottomNav');
          const josVizibil = (nav && nav.getClientRects().length ? nav.getBoundingClientRect().top : window.innerHeight) - 10;
          const josRand = rand.getBoundingClientRect().bottom + window.scrollY;
          if (josRand - tinta > josVizibil) tinta = josRand - josVizibil;
          window.scrollTo({ top: Math.max(0, tinta), behavior: 'smooth' });
          rand.classList.remove('slot-evidentiat');
          void rand.offsetWidth;
          rand.classList.add('slot-evidentiat');
        }, 120);
      };
    });
  };
  camp.addEventListener('input', deseneaza);
  trageInJosCaSaInchizi(foaie, inchideFisaScurta, '.fisa-scurta-maner');
  // Tastatura acoperă partea de jos a ecranului: fereastra urcă deasupra ei și se strânge pe spațiul rămas
  const vv = window.visualViewport;
  if (vv) {
    const urca = () => {
      if (!foaie.isConnected) { vv.removeEventListener('resize', urca); vv.removeEventListener('scroll', urca); return; }
      foaie.style.bottom = `${Math.max(0, window.innerHeight - vv.height - vv.offsetTop)}px`;
      foaie.style.maxHeight = `${Math.min(window.innerHeight * 0.8, vv.height - 24)}px`;
    };
    vv.addEventListener('resize', urca);
    vv.addEventListener('scroll', urca);
  }
  adaugaFoaieJos(fundal, foaie, inchideFisaScurta);
  sincronizeazaIstoricInapoi();
  setTimeout(() => camp.focus(), 60);
}

function inchideFisaScurta() {
  // Un câmp din fișă care încă are cursorul își salvează textul (blur) înainte să dispară fereastra
  const foaie = document.getElementById('fisaScurta');
  if (foaie && foaie.contains(document.activeElement)) document.activeElement.blur();
  foaie?.removeAttribute('id');
  coboaraFereastra(foaie, document.getElementById('fisaScurtaFundal'), () => foaie?.remove());
}

// Fără internet: etichetă sus, pentru că modificările din Orar nu se salvează fără conexiune
function actualizeazaEtichetaOffline() {
  let el = document.getElementById('etichetaOffline');
  if (navigator.onLine) { el?.remove(); return; }
  if (el) return;
  el = document.createElement('div');
  el.id = 'etichetaOffline';
  el.className = 'eticheta-offline';
  el.innerHTML = `<i></i>${tr('Fără internet · modificările nu se salvează acum', 'Offline · changes are not saved right now')}`;
  document.body.appendChild(el);
}
window.addEventListener('online', actualizeazaEtichetaOffline);
window.addEventListener('offline', actualizeazaEtichetaOffline);
document.addEventListener('DOMContentLoaded', actualizeazaEtichetaOffline);

function randeazaOrarInstant() {
  let container = document.getElementById('sloturiContainer');
  if (!container) return;
  let dataCalendarCurenta = getDataCalendaristicaCurenta();
  let saptamanaCheie = getSaptamanaCheie();
  let tagZiCautat = saptamanaCheie + "_" + ziCurentaCheie;
  let eTrecuta = esteSaptamanaTrecuta();
  // Săptămâna trecută e doar de citit: fără „Oră suplimentară” și fără cardul de final (vezi style.css)
  document.getElementById('tabOrar')?.classList.toggle('saptamana-trecuta', eTrecuta);
  // Săptămâna trecută: titlul fără cifre (și fără filtru). Celelalte primesc titlul cu cifrele la final; un apel
  // fără cifre aici anula filtrul ales la fiecare redesenare (de ex. la bifarea prezenței)
  if (eTrecuta) actualizeazaTitluOrar(null);

  let oreStandard = ["06:00", "07:00", "08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00"];

  if (eTrecuta) {
    let prezenteZi = (DB.prezente || []).filter(p => p && p.data === dataCalendarCurenta);
    let grupuriOreTrecute = {};
    prezenteZi.forEach(p => {
      if (!p.ora) return;
      let rawOra = normalizeazaOraUi(p.ora);
      if (!grupuriOreTrecute[rawOra]) grupuriOreTrecute[rawOra] = [];
      // Istoricul arată toate prezențele orei, indiferent de numărul de locuri setat acum
      grupuriOreTrecute[rawOra].push({
        ora: rawOra,
        clienta: p.clienta,
        antrenament: p.antrenament,
        bifat: true
      });
    });

    // Programări rămase neconfirmate (clientă trecută, fără bifă): se pot încă confirma (✓) sau șterge (✕)
    (DB.orarSloturi || []).forEach(s => {
      if (!s || s.bifat || !(s.clienta || '').trim()) return;
      if (s.ziRaw !== tagZiCautat && !(ziCurentaCheie === "Marti" && s.ziRaw === (saptamanaCheie + "_Marți"))) return;
      let rawOra = normalizeazaOraUi(s.ora);
      if (!grupuriOreTrecute[rawOra]) grupuriOreTrecute[rawOra] = [];
      grupuriOreTrecute[rawOra].push({
        ora: rawOra,
        clienta: s.clienta.trim(),
        antrenament: s.antrenament || '',
        bifat: false,
        slotIndex: Number(s.slotIndex) || 0
      });
    });

    let oreSet = Object.keys(grupuriOreTrecute).sort((a, b) => a.localeCompare(b));
    if (oreSet.length === 0) {
      container.innerHTML = `<div style="color:var(--text-muted); padding:24px; text-align:center;">${t('noPresence')}</div>`;
      return;
    }

    let htmlTrecut = '';
    oreSet.forEach(ora => {
      let lista = grupuriOreTrecute[ora];
      let historyText = currentLang === 'en' ? '✓ History' : '✓ Istoric';
      htmlTrecut += `
        <div class="hour-block" data-ora="${ora}">
          <div class="hour-header">
            <div class="hour-title-wrap"><span class="hour-icon-static">${ICON_CEAS_ORA}</span><span>${ora}</span></div>
            ${(() => {
              // Trecut: eticheta apare doar unde a rămas ceva neconfirmat (rândurile confirmate au deja „✓ Istoric”)
              const neconfirmate = lista.filter(s => !s.bifat).length;
              return neconfirmate ? `<div class="hour-badge hour-badge-neconfirmat">${neconfirmate} ${neconfirmate === 1 ? tr('neconfirmată', 'unconfirmed') : tr('neconfirmate', 'unconfirmed')}</div>` : '';
            })()}
          </div>
          <div class="hour-slots-wrapper">
      `;
      lista.forEach((s, idx) => {
        let colorCls = culoareAntrenament(s.antrenament);

        if (!s.bifat) {
          // Aceleași ID-uri ca în orarul curent: bifeazaPrezentaSlot / anuleazaSlot citesc numele și antrenamentul din ele
          let cheie = `${ora.replace(':', '')}_${s.slotIndex}`;
          htmlTrecut += `
          <div class="slot-row slot-occupied">
            <div class="slot-num">${idx + 1}</div>
            <div class="slot-info">
              <input type="text" id="cli_${cheie}" class="slot-input" value="${escAttr(s.clienta)}" readonly style="font-weight:700;">
              <input type="text" id="ant_${cheie}" class="slot-input ${colorCls}" value="${escAttr(traduceValoare(s.antrenament))}" data-valoare="${escAttr(s.antrenament)}" placeholder="-" readonly style="font-size:0.75rem; font-weight:700; margin-top:2px;">
            </div>
            <div style="display:flex; gap:4px;">
              <button id="btn_save_${cheie}" class="btn btn-save-check" title="${tr('Confirmă prezența (scade o ședință)', 'Confirm attendance (deducts a session)')}" onclick="bifeazaPrezentaSlot('${ziCurentaCheie}', '${ora}', ${s.slotIndex})">✓</button>
              <button id="btn_clear_${cheie}" class="btn btn-clear" title="${tr('Nu a venit: șterge programarea', 'Did not come: remove booking')}" onclick="anuleazaSlot('${ziCurentaCheie}', '${ora}', ${s.slotIndex})">✕</button>
            </div>
          </div>
        `;
          return;
        }

        htmlTrecut += `
          <div class="slot-row slot-occupied">
            <div class="slot-num">${idx + 1}</div>
            <div class="slot-info">
              <input type="text" class="slot-input" value="${escAttr(s.clienta)}" readonly style="font-weight:700;">
              <input type="text" class="slot-input ${colorCls}" value="${escAttr(traduceValoare(s.antrenament) || '-')}" readonly style="font-size:0.75rem; font-weight:700; margin-top:2px;">
            </div>
            <div style="font-size:0.82rem; font-weight:800; color:#15803d; padding:0 8px; white-space:nowrap;">${historyText}</div>
          </div>
        `;
      });
      htmlTrecut += `</div></div>`;
    });
    container.innerHTML = htmlTrecut;
    return;
  }

  let sloturi = (DB.orarSloturi || []).filter(s => {
    if (!s || !s.ziRaw) return false;
    let z = s.ziRaw.trim();
    if (z === tagZiCautat) return true;
    if (ziCurentaCheie === "Marti" && z === (saptamanaCheie + "_Marți")) return true;
    return false;
  });

  let grupuriOre = {};
  sloturi.forEach(slot => {
    if (!slot || !slot.ora) return;
    let rawOra = normalizeazaOraUi(slot.ora);
    if (!grupuriOre[rawOra]) grupuriOre[rawOra] = [];
    grupuriOre[rawOra].push(slot);
  });

  oreStandard.forEach(ora => {
    if (!grupuriOre[ora]) grupuriOre[ora] = [];
  });

  // Exact un loc pentru fiecare index (numărul de locuri vine din Setări): indexul lipsă se completează,
  // la rânduri dublate pe același index rămâne cel ocupat, altfel apar ID-uri dublate și numere decalate
  let nrLocuri = setariOrar.locuri;
  Object.keys(grupuriOre).forEach(ora => {
    let indexuri = Array.from({ length: nrLocuri }, (_, i) => i);
    // Dacă numărul de locuri s-a micșorat, locurile de peste rămân vizibile cât au clientă, prezență sau sunt deschise;
    // locul suplimentar (+ din antetul orei) rămâne și gol
    grupuriOre[ora].forEach(s => {
      let i = Number(s.slotIndex) || 0;
      if (i >= nrLocuri && (s.clienta || s.bifat || s.deschis || s.suplimentar) && !indexuri.includes(i)) indexuri.push(i);
    });
    indexuri.sort((a, b) => a - b);
    grupuriOre[ora] = indexuri.map(i => {
      let ale = grupuriOre[ora].filter(s => (Number(s.slotIndex) || 0) === i);
      return ale.find(s => s.clienta) || ale[0] || { row: null, ora: ora, clienta: "", antrenament: "", blocat: false, bifat: false, slotIndex: i };
    });
  });

  let oreSortate = Object.keys(grupuriOre).sort((a, b) => a.localeCompare(b));

  // „Acum” doar pe ziua de azi din săptămâna curentă; cifrele zilei (programați / prezenți / libere) pentru cardurile de sus
  let zileCheiAzi = ["Duminica", "Luni", "Marti", "Miercuri", "Joi", "Vineri", "Sambata"];
  let momentAcum = new Date();
  let oraAcum = (esteSaptamanaActiva() && ziCurentaCheie === zileCheiAzi[momentAcum.getDay()]) ? String(momentAcum.getHours()).padStart(2, '0') : null;
  let cifreZi = { programati: 0, prezenti: 0, libere: 0 };

  let html = '';
  oreSortate.forEach(ora => {
    let sloturiOra = grupuriOre[ora] || [];
    let esteBlocat = sloturiOra.some(s => s && s.blocat);
    let ocupate = sloturiOra.filter(s => s && s.clienta && s.clienta.trim() !== "").length;
    let total = sloturiOra.length;
    let bifati = sloturiOra.filter(s => s && s.bifat && s.clienta && s.clienta.trim() !== "").length;
    let esteAcum = oraAcum !== null && ora.slice(0, 2) === oraAcum;

    // Eticheta arată locurile libere; ora blocată (lacăt + chenar roșu) o are doar dacă are deja cliente programate
    let badgeHtml = '';
    let clientsBadgeHtml = '';
    let libere = Math.max(0, total - ocupate);
    if (!esteBlocat) {
      cifreZi.programati += ocupate;
      cifreZi.prezenti += bifati;
      cifreZi.libere += libere;
    }
    if (esteBlocat) {
      if (ocupate > 0) clientsBadgeHtml = `<div class="hour-badge hour-badge-busy">${ocupate} ${ocupate === 1 ? tr('programare', 'booking') : tr('programări', 'bookings')}</div>`;
    } else if (ocupate > 0 && bifati >= ocupate) {
      badgeHtml = `<div class="hour-badge hour-badge-prezenti">${tr('Toți prezenți', 'All present')}</div>`;
    } else {
      badgeHtml = `<div class="hour-badge ${ocupate > 0 ? 'hour-badge-busy' : 'hour-badge-free'}">${textLocuriLibere(libere)}</div>`;
    }

    let lockTitle = esteBlocat ? (currentLang === 'en' ? 'Unlock hour' : 'Deblochează ora') : (currentLang === 'en' ? 'Block hour' : 'Blochează ora');
    // Oră suplimentară: × o șterge cât e goală (stergeOraCustom); cu client pe ea, CSS-ul îl ascunde fără redesenare
    let stergeOraHtml = !oreStandard.includes(ora)
      ? `<button class="btn-sterge-ora" onclick="stergeOraCustom('${ziCurentaCheie}', '${ora}')" title="${tr('Șterge ora suplimentară', 'Remove extra hour')}" aria-label="${tr('Șterge ora suplimentară', 'Remove extra hour')}">×</button>`
      : '';

    html += `
      <div class="hour-block ${esteBlocat ? 'hour-block-blocked' : ''} ${esteAcum && !esteBlocat ? 'hour-block-acum' : ''}" data-ora="${ora}">
        <div class="hour-header">
          <div class="hour-title-wrap">
            <button class="btn-lock-hour" onclick="comutaBlocareOraInstant('${ziCurentaCheie}', '${ora}', ${!esteBlocat})" title="${lockTitle}" aria-label="${lockTitle}">
              ${esteBlocat ? ICON_LACAT_ORA : ICON_CEAS_ORA}
            </button>
            <span>${ora}</span>
            ${esteAcum ? `<span class="hour-acum"><i></i>${tr('Acum', 'Now')}</span>` : ''}
          </div>
          <div class="hour-header-dreapta">
            ${clientsBadgeHtml}
            ${badgeHtml}
            ${esteBlocat ? '' : `<button type="button" class="btn-adauga-loc" onclick="adaugaLocSuplimentar('${ziCurentaCheie}', '${ora}')" title="${tr('Adaugă un loc la această oră', 'Add a spot to this hour')}" aria-label="${tr('Adaugă un loc la această oră', 'Add a spot to this hour')}">+</button>`}
            ${stergeOraHtml}
          </div>
        </div>
        <div class="hour-slots-wrapper" ${esteBlocat ? 'style="pointer-events: none; user-select: none;"' : ''}>
    `;

    if (esteBlocat) {
      let motivCurent = (sloturiOra.find(s => s && s.motiv) || {}).motiv || '';
      html += `
        <div class="hour-motiv-overlay">
          <textarea class="hour-motiv-input" id="motiv_${ora.replace(':', '')}" rows="1" maxlength="300" placeholder="${tr('Motiv (opțional)', 'Reason (optional)')}" oninput="peSchimbareMotivOra('${ziCurentaCheie}', '${ora}')">${escAttr(motivCurent)}</textarea>
        </div>
      `;
    }

    let nebifati = 0;
    sloturiOra.forEach((slot, idx) => {
      let slotIdx = (typeof slot.slotIndex === 'number') ? slot.slotIndex : idx;
      let clientaCurata = (slot && slot.clienta) ? slot.clienta.trim() : "";
      let clientaValida = gasesteClientaValida(clientaCurata);
      let isOccupied = !!clientaValida;
      if (isOccupied && !slot.bifat) nebifati++;
      let antVal = (slot && slot.antrenament) ? slot.antrenament : "";
      let slotDomKey = `${ora.replace(':', '')}_${slotIdx}`;
      // Loc adăugat cu „+”, doar cât e peste numărul din Setări (după o mărire în Setări devine loc obișnuit)
      let esteLocSuplimentar = slot.suplimentar && slot.row && slotIdx >= nrLocuri;

      let colorCls = culoareAntrenament(antVal);

      let tipAntrenamentPlaceholder = currentLang === 'en' ? 'Workout type' : 'Tip antrenament';
      let clientPlaceholder = currentLang === 'en' ? 'Choose client' : 'Alege client';

      let selectAntHtml = `<select id="ant_${slotDomKey}" class="slot-select-type ${antVal ? 'select-active ' + colorCls : 'select-faded'}" onchange="aplicaCuloareAntrenament(this); peSchimbareAntrenament('${ziCurentaCheie}', '${ora}', ${slotIdx})">`;
      selectAntHtml += `<option value="" ${!antVal ? 'selected' : ''}>${tipAntrenamentPlaceholder}</option>`;
      // Tip șters sau redenumit între timp: rămâne în listă cât e salvat pe slot
      let tipuriSlot = optiuniAntrenamentConfig.map(opt => opt.text);
      if (antVal && !tipuriSlot.includes(antVal)) tipuriSlot.push(antVal);
      tipuriSlot.forEach(text => {
        let selected = (antVal === text) ? 'selected' : '';
        selectAntHtml += `<option value="${escAttr(text)}" ${selected}>${escAttr(traduceValoare(text))}</option>`;
      });
      selectAntHtml += `</select>`;

      // Bifa verde (prezent) rămâne apăsabilă: atingerea ei anulează prezența, după confirmare
      let prezent = isOccupied && slot.bifat;
      let saveBtnDisabledAttr = !isOccupied ? 'disabled' : '';
      let saveBtnClass = prezent ? 'btn btn-save-check btn-save-check-disabled btn-save-check-bifat'
        : !isOccupied ? 'btn btn-save-check btn-save-check-disabled' : 'btn btn-save-check';
      let saveBtnTitlu = prezent ? tr('Prezent (atinge ca să anulezi prezența)', 'Present (tap to undo attendance)') : tr('Bifează prezența și scade ședința', 'Mark attendance and deduct a session');
      let saveBtnClic = prezent ? `anuleazaPrezentaSlot('${ziCurentaCheie}', '${ora}', ${slotIdx})` : `bifeazaPrezentaSlot('${ziCurentaCheie}', '${ora}', ${slotIdx})`;

      let slotEsteCompletGol = !clientaCurata && !antVal;
      let clearBtnDisabledAttr = slotEsteCompletGol ? 'disabled' : '';
      let clearBtnClass = slotEsteCompletGol ? 'btn btn-clear btn-clear-disabled' : 'btn btn-clear';

      // Loc liber: numărul e și comutator „deschis pentru rezervări"; loc rezervat de clientă: număr marcat
      // Numărul arată poziția în oră, nu indexul: după ștergerea unui loc suplimentar din mijloc nu rămân goluri
      let slotNumHtml = `<div class="slot-num">${idx + 1}</div>`;
      if (!isOccupied && !slot.bifat) {
        let titluDeschis = slot.deschis ? tr('Deschis pentru rezervări (apasă ca să închizi)', 'Open for booking (tap to close)') : tr('Închis pentru rezervări (apasă ca să deschizi)', 'Closed for booking (tap to open)');
        slotNumHtml = `<button type="button" class="slot-num slot-num-btn ${slot.deschis ? 'slot-deschis' : ''}" title="${titluDeschis}" onclick="comutaSlotDeschis('${ziCurentaCheie}', '${ora}', ${slotIdx})">${idx + 1}</button>`;
      } else if (slot.rezervatOnline) {
        slotNumHtml = `<div class="slot-num slot-num-online" title="${tr('Rezervat de client', 'Booked by the client')}">${idx + 1}</div>`;
      }
      // Loc ocupat: inițialele clientului sau poza de profil, dacă și-a pus una în cont
      if (isOccupied) {
        let titluLoc = escAttr(clientaValida.nume) + (slot.rezervatOnline ? ' · ' + tr('Rezervat de client', 'Booked by the client') : '');
        slotNumHtml = `<div class="slot-num slot-num-client${slot.rezervatOnline ? ' slot-num-online' : ''}" role="button" tabindex="0" title="${titluLoc}" onclick="arataFisaScurta('${escAttr(clientaValida.id)}', '${ziCurentaCheie}', '${ora}', ${slotIdx})">${avatarSlotHtml(clientaValida)}</div>`;
      }

      // Etichete lângă tipul de antrenament: loc deschis rezervărilor; abonament aproape terminat (doar abonamente cu ședințe)
      let eticheteSlot = '';
      if (!isOccupied && !slot.bifat && slot.deschis) {
        eticheteSlot += `<span class="slot-eticheta slot-eticheta-deschis"><i></i>${tr('Deschis rezervărilor', 'Open for booking')}</span>`;
      }
      if (isOccupied && clientaValida.incluse > 0 && clientaValida.ramase <= 1) {
        eticheteSlot += clientaValida.ramase <= 0
          ? `<span class="slot-eticheta slot-eticheta-terminat">${tr('Abonament terminat', 'Membership used up')}</span>`
          : `<span class="slot-eticheta slot-eticheta-ramas">${tr('1 ședință rămasă', '1 session left')}</span>`;
      }

      html += `
        <div class="slot-row ${isOccupied ? 'slot-occupied' : 'slot-free'}${esteLocSuplimentar ? ' slot-suplimentar' : ''}" data-stare="${!clientaCurata ? 'liber' : slot.bifat ? 'prezent' : 'programat'}">
          ${slotNumHtml}
          <div class="slot-info">
            <input type="text" id="cli_${slotDomKey}" class="slot-input" value="${escAttr(clientaCurata)}" placeholder="${clientPlaceholder}" list="listaClienteVizibile" autocomplete="off" oninput="peSchimbareNumeClienta('${ziCurentaCheie}', '${ora}', ${slotIdx}, event)">
            <div class="slot-etichete">${selectAntHtml}${eticheteSlot}</div>
          </div>
          <div style="display:flex; gap:4px;">
            <button id="btn_save_${slotDomKey}" class="${saveBtnClass}" ${saveBtnDisabledAttr} title="${saveBtnTitlu}" aria-label="${saveBtnTitlu}" onclick="${saveBtnClic}">✓</button>
            <button id="btn_clear_${slotDomKey}" class="${clearBtnClass}" ${clearBtnDisabledAttr} title="${tr('Golește slotul și șterge din istoric', 'Clear the slot and remove it from history')}" aria-label="${tr('Golește slotul și șterge din istoric', 'Clear the slot and remove it from history')}" onclick="anuleazaSlot('${ziCurentaCheie}', '${ora}', ${slotIdx})">✕</button>
            ${esteLocSuplimentar ? `<button type="button" class="btn-sterge-ora btn-sterge-loc" onclick="stergeLocSuplimentar('${ziCurentaCheie}', '${ora}', ${slot.row})" title="${tr('Șterge locul suplimentar', 'Remove extra spot')}" aria-label="${tr('Șterge locul suplimentar', 'Remove extra spot')}">×</button>` : ''}
          </div>
        </div>
      `;
    });

    // Oră cu cel puțin doi clienți, din care măcar unul nebifat: un singur buton pentru toată ora (cu confirmare)
    if (!esteBlocat && ocupate >= 2 && nebifati >= 1 && !ziAleasaInViitor()) {
      html += `<button type="button" class="btn-bifeaza-ora" onclick="bifeazaToataOra('${ziCurentaCheie}', '${ora}')">
        <span class="btn-bifeaza-ora-bifa">✓</span>${tr('Bifează toți clienții', 'Mark all clients')} (${nebifati})</button>`;
    }

    html += `</div></div>`;
  });

  container.innerHTML = html;
  actualizeazaTitluOrar(cifreZi);
  reaplicaBifariTrimise();
  container.querySelectorAll('.hour-motiv-input').forEach(potrivesteInaltimeNotita);
}

// Notița orei blocate crește cu textul. Unde CSS nu are `field-sizing` (Safari mai vechi), înălțimea se pune din JS,
// imediat după randare, ca să fie măsurată corect de calibreazaLayoutEcran
const ARE_FIELD_SIZING = typeof CSS !== 'undefined' && CSS.supports && CSS.supports('field-sizing', 'content');
function potrivesteInaltimeNotita(el) {
  if (ARE_FIELD_SIZING || !el) return;
  el.style.height = 'auto';
  el.style.height = Math.min(el.scrollHeight + 2, 120) + 'px';
}

// Deschide/închide un loc liber pentru rezervările clientelor. Locul se creează în baza de date dacă nu există încă.
function comutaSlotDeschis(zi, ora, slotIdx) {
  const saptamanaCheie = getSaptamanaCheie();
  const oraNorm = normalizeazaOraUi(ora);
  const tagZi = saptamanaCheie + '_' + zi;
  let slot = (DB.orarSloturi || []).find(s => s && (s.ziRaw === tagZi || (zi === 'Marti' && s.ziRaw === saptamanaCheie + '_Marți')) && normalizeazaOraUi(s.ora) === oraNorm && (Number(s.slotIndex) || 0) === slotIdx);
  const nou = !(slot && slot.deschis);
  if (!slot) {
    slot = { row: null, ziRaw: tagZi, ora: oraNorm, clienta: '', antrenament: '', blocat: false, bifat: false, slotIndex: slotIdx, deschis: false, rezervatOnline: false };
    DB.orarSloturi.push(slot);
  }
  slot.deschis = nou;
  randeazaOrarInstant();
  callBackend("seteazaSlotDeschis", { saptamanaCheie: saptamanaCheie, zi: zi, ora: oraNorm, slotIndex: slotIdx, row: slot.row, deschis: nou }, function(res) {
    if (res && res.row) slot.row = res.row;
    try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}
  }, function() {
    slot.deschis = !nou;
    randeazaOrarInstant();
  });
}

// O blocare/deblocare în curs: o a doua atingere pe ceas/lacăt ar putea crea rânduri duplicate în baza de date
let blocareOraInCurs = false;

function comutaBlocareOraInstant(zi, ora, blocatNou) {
  if (blocareOraInCurs) {
    showToast(tr("Se salvează, încearcă din nou în câteva secunde", "Saving, try again in a few seconds"), "error");
    return;
  }
  let saptamanaCheie = getSaptamanaCheie();
  let tagZiCautat = saptamanaCheie + "_" + zi;
  let oraNorm = normalizeazaOraUi(ora);
  let textConfirm = blocatNou ? 
    (currentLang === 'en' ? `Block time slot ${oraNorm}?` : `Blochezi intervalul orar ${oraNorm}?`) : 
    (currentLang === 'en' ? `Unblock time slot ${oraNorm}?` : `Deblochezi intervalul orar ${oraNorm}?`);
  const sloturiOra = (DB.orarSloturi || []).filter(s => (s.ziRaw === tagZiCautat || s.ziRaw === (saptamanaCheie + "_Marți")) && normalizeazaOraUi(s.ora) === oraNorm);
  // Motivul se cere doar la blocare, cu câmpul gol; la deblocare se șterge
  const camp = blocatNou ? { placeholder: tr('Motiv (opțional)', 'Reason (optional)') } : undefined;

  customConfirm(currentLang === 'en' ? "Time Slot Locking" : "Blocare oră", textConfirm, function(motivNou) {
    sloturiOra.forEach(s => {
      s.blocat = blocatNou;
      s.motiv = blocatNou ? motivNou : '';
    });
    randeazaOrarInstant();
    try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}

    const payload = { saptamanaCheie: saptamanaCheie, zi: zi, ora: oraNorm, blocat: blocatNou };
    payload.motiv = blocatNou ? motivNou : '';
    blocareOraInCurs = true;
    callBackend("comutaBlocareOra", payload, function() {
      blocareOraInCurs = false;
      showToast(blocatNou ? 
        (currentLang === 'en' ? `✓ Time slot ${oraNorm} has been blocked!` : `✓ Intervalul ${oraNorm} a fost blocat!`) : 
        (currentLang === 'en' ? `✓ Time slot ${oraNorm} has been unblocked!` : `✓ Intervalul ${oraNorm} a fost deblocat!`)
      );
      incarcaBazaDateSilencios();
    }, function() { blocareOraInCurs = false; });
  }, camp);
}

// Notița orei blocate se salvează singură, la o scurtă pauză după ultima tastă
let debounceTimerMotiv = null;
function peSchimbareMotivOra(zi, ora) {
  let oraNorm = normalizeazaOraUi(ora);
  let el = document.getElementById('motiv_' + oraNorm.replace(':', ''));
  if (!el) return;
  potrivesteInaltimeNotita(el);
  let saptamanaCheie = getSaptamanaCheie();
  let tagZiCautat = saptamanaCheie + "_" + zi;
  let motiv = el.value.trim();

  (DB.orarSloturi || []).forEach(s => {
    if ((s.ziRaw === tagZiCautat || s.ziRaw === (saptamanaCheie + "_Marți")) && normalizeazaOraUi(s.ora) === oraNorm) s.motiv = motiv;
  });

  clearTimeout(debounceTimerMotiv);
  debounceTimerMotiv = setTimeout(() => {
    try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}
    callBackend("salveazaMotivOra", { saptamanaCheie: saptamanaCheie, zi: zi, ora: oraNorm, motiv: motiv });
  }, 700);
}

let debounceTimerNume = null;

// „Arată programarea”: locul existent ajunge în mijlocul ecranului și pulsează ca ora curentă
function arataLocExistent(slot) {
  const ora = normalizeazaOraUi(slot.ora);
  const rand = document.getElementById('cli_' + ora.replace(':', '') + '_' + (Number(slot.slotIndex) || 0))?.closest('.slot-row');
  if (!rand) return;
  rand.scrollIntoView({ behavior: 'auto', block: 'center' });
  rand.classList.remove('slot-evidentiat');
  void rand.offsetWidth;
  rand.classList.add('slot-evidentiat');
  setTimeout(() => rand.classList.remove('slot-evidentiat'), DURATA_HIGHLIGHT_ORA + 100);
}

// Clienta are deja un loc în ziua afișată. Aceeași oră: blocat (cu „Arată programarea”).
// Altă oră: avertizare, iar „Adaugă oricum” salvează (adaugaOricum).
function arataProgramareaExistenta(nume, slot, oraNoua, adaugaOricum) {
  const ora = normalizeazaOraUi(slot.ora);
  const zi = ((getZileConfig().find(z => z.cheie === ziCurentaCheie) || {}).nume || '').toLowerCase();
  if (ora === oraNoua) {
    customConfirm(
      tr('Are deja o programare la această oră', 'Already booked at this time'),
      tr(`${nume} are deja o programare ${zi} la ${ora}. Nu poate ocupa două locuri la aceeași oră.`,
         `${nume} is already booked on ${zi} at ${ora}. They cannot take two spots at the same time.`),
      function() { arataLocExistent(slot); }
    );
    document.getElementById('modalBtnConfirm').innerText = tr('Arată programarea', 'Show booking');
    return;
  }
  customConfirm(
    tr('Încă o programare în aceeași zi', 'Another booking on the same day'),
    tr(`${nume} are deja o programare ${zi} la ${ora}. Adaugi o programare și la ${oraNoua}?`,
       `${nume} already has a booking on ${zi} at ${ora}. Add them at ${oraNoua} too?`),
    function() {
      adaugaOricum();
      randeazaOrarInstant();
    }
  );
  document.getElementById('modalBtnConfirm').innerText = tr('Adaugă oricum', 'Add anyway');
}
function seteazaStilSlotOcupat(elCli, ocupat) {
  let rand = elCli ? elCli.closest('.slot-row') : null;
  if (!rand) return;
  rand.classList.toggle('slot-occupied', ocupat);
  rand.classList.toggle('slot-free', !ocupat);

  let bloc = rand.closest('.hour-block');
  let badge = bloc ? bloc.querySelector('.hour-badge-busy, .hour-badge-free') : null;
  if (!badge) return;
  let inputs = bloc.querySelectorAll('.slot-input');
  let nr = 0;
  inputs.forEach(inp => { if (gasesteClientaValida(inp.value.trim())) nr++; });
  badge.textContent = textLocuriLibere(inputs.length - nr);
  badge.classList.toggle('hour-badge-busy', nr > 0);
  badge.classList.toggle('hour-badge-free', nr === 0);
}

function peSchimbareNumeClienta(zi, ora, slotIdx, ev) {
  let oraNorm = normalizeazaOraUi(ora);
  let slotDomKey = `${oraNorm.replace(':', '')}_${slotIdx}`;
  let elCli = document.getElementById('cli_' + slotDomKey);
  let elBtnSave = document.getElementById('btn_save_' + slotDomKey);
  let elBtnClear = document.getElementById('btn_clear_' + slotDomKey);
  let textIntrodus = elCli ? elCli.value.trim() : "";
  let clientaGasita = gasesteClientaValida(textIntrodus);
  seteazaStilSlotOcupat(elCli, !!clientaGasita);

  // Alegere din listă (nu tastare): ieșim din câmp, salvarea pornește oricum după debounce
  let dinLista = ev && (ev.inputType === 'insertReplacementText' || !ev.inputType);
  if (clientaGasita && dinLista && elCli) elCli.blur();

  if (elBtnSave) {
    if (clientaGasita) {
      elBtnSave.disabled = false;
      elBtnSave.classList.remove('btn-save-check-disabled');
    } else {
      elBtnSave.disabled = true;
      elBtnSave.classList.add('btn-save-check-disabled');
    }
  }

  if (elBtnClear) {
    let elAnt = document.getElementById('ant_' + slotDomKey);
    let areCevaCompletat = (textIntrodus !== "") || (elAnt && elAnt.value !== "");
    elBtnClear.disabled = !areCevaCompletat;
    if (areCevaCompletat) {
      elBtnClear.classList.remove('btn-clear-disabled');
    } else {
      elBtnClear.classList.add('btn-clear-disabled');
    }
  }

  clearTimeout(debounceTimerNume);
  debounceTimerNume = setTimeout(() => {
    let elAnt = document.getElementById('ant_' + slotDomKey);
    let antrenament = elAnt ? (elAnt.dataset.valoare ?? elAnt.value) : "";
    let saptamanaCheie = getSaptamanaCheie();
    let dataCalendar = getDataCalendaristicaCurenta();
    let tagZi = saptamanaCheie + "_" + zi;

    let slotExistent = (DB.orarSloturi || []).find(s => {
      if (!s || !s.ziRaw) return false;
      let rawOra = normalizeazaOraUi(s.ora);
      return (s.ziRaw === tagZi || (zi === "Marti" && s.ziRaw === (saptamanaCheie + "_Marți"))) && 
             rawOra === oraNorm && 
             Number(s.slotIndex) === Number(slotIdx);
    });
    let rowNum = slotExistent ? slotExistent.row : null;

    if (!textIntrodus) {
      if (slotExistent) {
        slotExistent.clienta = "";
        slotExistent.antrenament = "";
        slotExistent.bifat = false;
        try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}
      }
      callBackend("salveazaSlotAuto", {
        row: rowNum, saptamanaCheie: saptamanaCheie, dataCalendar: dataCalendar, zi: zi, ora: oraNorm, clienta: "", antrenament: "", slotIndex: slotIdx
      }, function() {
        incarcaBazaDateSilencios();
      });
      return;
    }

    if (!clientaGasita) return;

    let numeExact = clientaGasita.nume;

    // Aceeași clientă în aceeași zi: la aceeași oră e blocat; la altă oră se poate, după avertizare
    let dubluri = (DB.orarSloturi || []).filter(s => s &&
      (s.ziRaw === tagZi || (zi === "Marti" && s.ziRaw === (saptamanaCheie + "_Marți"))) &&
      (s.clienta || '').trim().toLowerCase() === numeExact.toLowerCase() &&
      !(normalizeazaOraUi(s.ora) === oraNorm && Number(s.slotIndex) === Number(slotIdx)))
      .sort((a, b) => normalizeazaOraUi(a.ora).localeCompare(normalizeazaOraUi(b.ora)));
    let dublura = dubluri.find(s => normalizeazaOraUi(s.ora) === oraNorm) || dubluri[0];
    if (dublura) {
      if (elCli) elCli.blur();
      randeazaOrarInstant(); // locul revine la ce era salvat; se completează doar dacă antrenorul confirmă
      arataProgramareaExistenta(numeExact, dublura, oraNorm, salveazaInSlot);
      return;
    }
    salveazaInSlot();

    function salveazaInSlot() {
    if (elCli && elCli.value !== numeExact) {
      elCli.value = numeExact;
    }
    const avertizare = mesajAntrenamentRepetat(numeExact, antrenament, saptamanaCheie, oraNorm, slotIdx, slotExistent ? slotExistent.ziRaw : tagZi);
    if (avertizare) showToast('⚠ ' + avertizare, 'error');

    if (slotExistent) {
      slotExistent.clienta = numeExact;
      slotExistent.antrenament = antrenament;
    } else {
      DB.orarSloturi.push({
        row: null,
        ziRaw: tagZi,
        ora: oraNorm,
        clienta: numeExact,
        antrenament: antrenament,
        blocat: false,
        bifat: false,
        slotIndex: slotIdx
      });
    }
    try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}

    callBackend("salveazaSlotAuto", {
      row: rowNum, saptamanaCheie: saptamanaCheie, dataCalendar: dataCalendar, zi: zi, ora: oraNorm, clienta: numeExact, antrenament: antrenament, slotIndex: slotIdx
    }, function(res) {
      if (res && res.row && slotExistent) {
        slotExistent.row = res.row;
        try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}
      }
      incarcaBazaDateSilencios();
    });
    }
  }, 400);
}

// Același tip de antrenament pentru același client, de două ori în săptămână: doar avertizare, se salvează oricum
function mesajAntrenamentRepetat(numeExact, antrenament, saptamanaCheie, oraNorm, slotIdx, tagZi) {
  const ant = (antrenament || '').trim().toLowerCase();
  if (!ant) return '';
  const repetat = (DB.orarSloturi || []).some(s => s && String(s.ziRaw || '').startsWith(saptamanaCheie + '_') &&
    (s.clienta || '').trim().toLowerCase() === numeExact.toLowerCase() &&
    (s.antrenament || '').trim().toLowerCase() === ant &&
    !(s.ziRaw === tagZi && normalizeazaOraUi(s.ora) === oraNorm && Number(s.slotIndex) === Number(slotIdx)));
  return repetat ? tr(`${numeExact} are deja un antrenament de ${traduceValoare(antrenament)} în această săptămână.`, `${numeExact} already has a ${traduceValoare(antrenament)} workout this week.`) : '';
}

function peSchimbareAntrenament(zi, ora, slotIdx) {
  let oraNorm = normalizeazaOraUi(ora);
  let slotDomKey = `${oraNorm.replace(':', '')}_${slotIdx}`;
  let elCli = document.getElementById('cli_' + slotDomKey);
  let elAnt = document.getElementById('ant_' + slotDomKey);
  let elBtnClear = document.getElementById('btn_clear_' + slotDomKey);
  let textIntrodus = elCli ? elCli.value.trim() : "";
  let antrenament = elAnt ? (elAnt.dataset.valoare ?? elAnt.value) : "";
  let clientaGasita = gasesteClientaValida(textIntrodus);

  if (elBtnClear) {
    let areCeva = (textIntrodus !== "") || (antrenament !== "");
    elBtnClear.disabled = !areCeva;
    if (areCeva) elBtnClear.classList.remove('btn-clear-disabled');
    else elBtnClear.classList.add('btn-clear-disabled');
  }

  if (!clientaGasita) {
    showToast(currentLang === 'en' ? "Please choose an active existing client first!" : "Alege mai întâi un client activ existent!", "error");
    if (elAnt) {
      elAnt.value = "";
      aplicaCuloareAntrenament(elAnt);
    }
    return;
  }

  let numeExact = clientaGasita.nume;
  let saptamanaCheie = getSaptamanaCheie();
  let dataCalendar = getDataCalendaristicaCurenta();
  let tagZi = saptamanaCheie + "_" + zi;

  let slotExistent = (DB.orarSloturi || []).find(s => {
    if (!s || !s.ziRaw) return false;
    let rawOra = normalizeazaOraUi(s.ora);
    return (s.ziRaw === tagZi || (zi === "Marti" && s.ziRaw === (saptamanaCheie + "_Marți"))) && 
           rawOra === oraNorm && 
           Number(s.slotIndex) === Number(slotIdx);
  });
  let rowNum = slotExistent ? slotExistent.row : null;
  const avertizare = mesajAntrenamentRepetat(numeExact, antrenament, saptamanaCheie, oraNorm, slotIdx, slotExistent ? slotExistent.ziRaw : tagZi);

  if (slotExistent) {
    slotExistent.clienta = numeExact;
    slotExistent.antrenament = antrenament;
    // Locul e deja bifat: prezența din istoric primește și ea antrenamentul (altfel rămâne cel de la bifare, de obicei „-”)
    if (slotExistent.bifat) actualizeazaAntrenamentPrezenta(dataCalendar, oraNorm, numeExact, antrenament);
    try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}
  }

  callBackend("salveazaSlotAuto", {
    row: rowNum, saptamanaCheie: saptamanaCheie, dataCalendar: dataCalendar, zi: zi, ora: oraNorm, clienta: numeExact, antrenament: antrenament, slotIndex: slotIdx
  }, function(res) {
    if (res && res.row && slotExistent) {
      slotExistent.row = res.row;
      try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}
    }
    if (avertizare) showToast('⚠ ' + avertizare, 'error');
    else showToast(antrenament ? t('toastWorkoutSaved') : tr('✓ Antrenament scos', '✓ Workout removed'));
  });
}

// Doar textul antrenamentului din prezență (aceeași potrivire ca la bifare: dată + oră + client); numărul de ședințe nu se schimbă.
// Memoria se actualizează pe loc (cache-ul local îl scrie apelantul), baza în fundal.
async function actualizeazaAntrenamentPrezenta(data, ora, clienta, antrenament) {
  const p = (DB.prezente || []).find(x => x && x.data === data && normalizeazaOraUi(x.ora || '') === ora && cheieNume(x.clienta || '') === cheieNume(clienta));
  if (p) p.antrenament = antrenament;
  if (!supabaseClient) return;
  let q = supabaseClient.from('prezente').update({ antrenament: antrenament || '' }).eq('data', data).eq('ora', ora).ilike('clienta', clienta.trim());
  if (utilizatorCurent) q = q.eq('user_id', utilizatorCurent.id);
  const { error } = await q;
  if (error) showToast(tr('Antrenamentul nu s-a salvat în istoric. Verifică internetul și reîncearcă.', 'The workout was not saved to the history. Check your internet and try again.'), 'error');
}

// ✓ pe un loc: se trimite imediat (ca înainte), cu o vibrație scurtă pe telefoanele care o permit
function bifeazaPrezentaSlot(zi, ora, slotIdx) {
  if (ziAleasaInViitor()) return avizBifareViitor();
  let d = pregatesteBifare(zi, ora, slotIdx);
  if (!d) {
    showToast(currentLang === 'en' ? "Choose a valid client from the list!" : "Alege un client valid din listă!", "error");
    return;
  }
  // Un loc bifat nu se mai trimite a doua oară (altfel baza scade încă o ședință), până nu e eliberat
  if (bifariTrimise.has(cheieBifare(d))) return;
  bifariTrimise.add(cheieBifare(d));
  try { if (navigator.vibrate) navigator.vibrate(12); } catch (e) {}
  trimiteBifarePrezenta(d);
  showToast(t('toastPresenceMarked'));
}

// Locurile bifate în această sesiune: cheia e săptămâna + ziua + locul
var bifariTrimise = new Set();
function cheieBifare(d) { return `${d.saptamanaCheie}|${d.zi}|${d.slotDomKey}|${d.numeExact.trim().toLowerCase()}`; }

// După o redesenare (de ex. datele reîncărcate înainte ca baza să confirme bifarea), ✓ rămâne bifat
function reaplicaBifariTrimise() {
  const sapt = getSaptamanaCheie();
  bifariTrimise.forEach(k => {
    const [s, zi, slotDomKey, nume] = k.split('|');
    if (s !== sapt || zi !== ziCurentaCheie) return;
    // Doar dacă în loc e tot același client (altul nou pus în locul lui se poate bifa)
    const cli = document.getElementById('cli_' + slotDomKey);
    if (!cli || cli.value.trim().toLowerCase() !== nume) return;
    // Bifa verde rămâne apăsabilă (atingerea anulează prezența); a doua trimitere o oprește bifeazaPrezentaSlot
    const btn = document.getElementById('btn_save_' + slotDomKey);
    if (btn) btn.classList.add('btn-save-check-disabled', 'btn-save-check-bifat');
  });
}

// Citește locul din pagină în momentul apăsării (nume, antrenament, zi, săptămână)
function pregatesteBifare(zi, ora, slotIdx) {
  let oraNorm = normalizeazaOraUi(ora);
  let slotDomKey = `${oraNorm.replace(':', '')}_${slotIdx}`;
  let elCli = document.getElementById('cli_' + slotDomKey);
  let elAnt = document.getElementById('ant_' + slotDomKey);
  let clientaGasita = gasesteClientaValida(elCli ? elCli.value.trim() : "");
  if (!clientaGasita) return null;
  return {
    zi, ora: oraNorm, slotIdx, slotDomKey,
    numeExact: clientaGasita.nume,
    antrenament: elAnt ? (elAnt.dataset.valoare ?? elAnt.value) : "",
    dataCalendar: getDataCalendaristicaCurenta(),
    saptamanaCheie: getSaptamanaCheie()
  };
}

// „Bifează toată ora”: toți clienții nebifați ai orei, după confirmare; fiecare bifare e cea de la ✓
function bifeazaToataOra(zi, ora) {
  if (ziAleasaInViitor()) return avizBifareViitor();
  let bloc = document.querySelector(`#sloturiContainer .hour-block[data-ora="${ora}"]`);
  if (!bloc) return;
  let lista = [];
  bloc.querySelectorAll('.btn-save-check:not(:disabled):not(.btn-save-check-bifat)').forEach(btn => {
    let idx = Number(btn.id.split('_').pop());
    let d = pregatesteBifare(zi, ora, idx);
    if (d) lista.push(d);
  });
  if (!lista.length) return;
  let nume = lista.map(d => d.numeExact).join(', ');
  customConfirm(
    tr(`Bifezi toată ora ${ora}?`, `Mark the whole ${ora} hour?`),
    tr(`Se marchează prezența pentru ${nume} și se scade câte o ședință din abonament.`, `Attendance is marked for ${nume} and one session is deducted from each membership.`),
    () => {
      try { if (navigator.vibrate) navigator.vibrate([12, 40, 12]); } catch (e) {}
      lista = lista.filter(d => !bifariTrimise.has(cheieBifare(d)));
      lista.forEach(d => { bifariTrimise.add(cheieBifare(d)); trimiteBifarePrezenta(d); });
      showToast(tr(`Ora ${ora} bifată`, `${ora} marked`));
    }
  );
}

// Glisare în Orar: pe un rând spre dreapta = ✓, spre stânga = ✕ (apasă chiar butoanele, cu aceleași verificări);
// în afara rândurilor, spre stânga / dreapta = ziua următoare / anterioară
(function initGlisareOrar() {
  const tab = document.getElementById('tabOrar');
  const cont = document.getElementById('sloturiContainer');
  if (!tab || !cont) return;
  let g = null;
  let ziStart = null;
  let opresteClick = false;
  const PRAG = 64; // px trași pentru Prezent / Golește; o glisare scurtă dar rapidă ajunge și ea

  cont.addEventListener('click', e => {
    if (opresteClick) { e.stopPropagation(); e.preventDefault(); opresteClick = false; }
  }, true);

  tab.addEventListener('pointerdown', e => {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const row = e.target.closest('#sloturiContainer .slot-row');
    if (!row) {
      if (!e.target.closest('.day-selector, .calendar-expandable-card, input, textarea, select, details')) ziStart = { x: e.clientX, y: e.clientY };
      return;
    }
    if (e.target.closest('select') || row.closest('.hour-block-blocked')) return;
    // Lângă marginile ecranului începe gestul „Înapoi” al telefonului (Android): acolo nu pornim glisarea pe rând,
    // altfel telefonul face și „Înapoi” și aplicația sare pe alt ecran
    if (e.pointerType === 'touch' && (e.clientX < 28 || e.clientX > window.innerWidth - 28)) return;
    const save = row.querySelector('.btn-save-check');
    const clear = row.querySelector('.btn-clear');
    const poateBifa = !!(save && !save.disabled && !save.classList.contains('btn-save-check-bifat') && !ziAleasaInViitor());
    const poateElibera = !!(clear && !clear.disabled);
    if (!poateBifa && !poateElibera) return;
    g = { row, save, clear, poateBifa, poateElibera, x: e.clientX, y: e.clientY, id: e.pointerId, activ: false, dx: 0 };
  });

  tab.addEventListener('pointermove', e => {
    if (!g || e.pointerId !== g.id) return;
    let dx = e.clientX - g.x;
    const dy = e.clientY - g.y;
    if (!g.activ) {
      if (Math.abs(dy) > 10 && Math.abs(dy) > Math.abs(dx)) { g = null; return; }
      if (Math.abs(dx) < 8) return;
      g.activ = true;
      try { g.row.setPointerCapture(e.pointerId); } catch (x) {}
      g.fundal = document.createElement('div');
      g.fundal.className = 'glisare-fundal';
      g.fundal.innerHTML = `<span class="glisare-actiune glisare-bifa"><i>✓</i>${tr('Prezent', 'Present')}</span><span class="glisare-actiune glisare-elibereaza">${tr('Golește', 'Clear')}<i>✕</i></span>`;
      g.fundal.style.top = g.row.offsetTop + 'px';
      g.fundal.style.height = g.row.offsetHeight + 'px';
      g.row.parentElement.insertBefore(g.fundal, g.row);
      g.row.classList.add('glisare-activ');
    }
    if (dx > 0 && !g.poateBifa) dx /= 4;
    if (dx < 0 && !g.poateElibera) dx /= 4;
    const acum = performance.now();
    if (g.t) g.v = (Math.max(-150, Math.min(150, dx)) - g.dx) / Math.max(1, acum - g.t); // px/ms, pentru „aruncare”
    g.t = acum;
    g.dx = Math.max(-150, Math.min(150, dx));
    g.row.style.transform = `translateX(${g.dx}px)`;
    g.fundal.classList.toggle('spre-dreapta', g.dx > 0);
    // Cât s-a tras (0–1) pentru iconiță; peste prag, iconița „se aprinde” și telefonul vibrează scurt o dată
    g.fundal.style.setProperty('--p', Math.min(1, Math.abs(g.dx) / PRAG).toFixed(2));
    const pestePrag = (g.dx > PRAG && g.poateBifa) || (g.dx < -PRAG && g.poateElibera);
    if (pestePrag !== !!g.prag) {
      g.prag = pestePrag;
      g.fundal.classList.toggle('prag', pestePrag);
      if (pestePrag) { try { if (navigator.vibrate) navigator.vibrate(8); } catch (x) {} }
    }
  });

  const gata = e => {
    if (ziStart && !g) {
      const dx = e.clientX - ziStart.x;
      const dy = e.clientY - ziStart.y;
      ziStart = null;
      if (e.type === 'pointerup' && Math.abs(dx) > 70 && Math.abs(dx) > 2 * Math.abs(dy)) mergiLaZiVecina(dx < 0 ? 1 : -1);
      return;
    }
    ziStart = null;
    if (!g) return;
    const s = g;
    g = null;
    if (!s.activ) return;
    if (e.type === 'pointerup') {
      // Peste prag sau „aruncat” (minim 36px, peste 0,5 px/ms în aceeași direcție)
      const aruncat = Math.abs(s.dx) > 36 && Math.abs(s.v || 0) > 0.5 && Math.sign(s.v) === Math.sign(s.dx);
      if ((s.dx > PRAG || (aruncat && s.dx > 0)) && s.poateBifa) s.save.click();
      else if ((s.dx < -PRAG || (aruncat && s.dx < 0)) && s.poateElibera) s.clear.click();
    }
    // Click-ul care urmează după ridicarea degetului nu mai apasă ce era sub deget
    opresteClick = true;
    setTimeout(() => { opresteClick = false; }, 350);
    s.row.classList.add('glisare-revine');
    s.row.style.transform = '';
    setTimeout(() => {
      s.row.classList.remove('glisare-activ', 'glisare-revine');
      s.fundal.remove();
    }, 300);
  };
  tab.addEventListener('pointerup', gata);
  tab.addEventListener('pointercancel', gata);
})();

// Ziua următoare / anterioară din bara de zile, cu intrare animată din partea în care s-a glisat
function mergiLaZiVecina(pas) {
  const zile = getZileConfig();
  const i = zile.findIndex(z => z.cheie === ziCurentaCheie);
  const urm = zile[i + pas];
  if (i < 0 || !urm) return;
  schimbaZiInstant(urm.cheie);
  const cont = document.getElementById('sloturiContainer');
  if (!cont) return;
  cont.classList.remove('zi-intra-dreapta', 'zi-intra-stanga');
  void cont.offsetWidth;
  cont.classList.add(pas > 0 ? 'zi-intra-dreapta' : 'zi-intra-stanga');
}

// Trimiterea propriu-zisă a unei prezențe (fosta parte a lui bifeazaPrezentaSlot, neschimbată)
function trimiteBifarePrezenta(d) {
  let { zi, slotIdx, numeExact, antrenament, dataCalendar, saptamanaCheie } = d;
  let oraNorm = d.ora;
  let slotDomKey = d.slotDomKey;
  let tagZi = saptamanaCheie + "_" + zi;

  let slotExistent = (DB.orarSloturi || []).find(s => {
    if (!s || !s.ziRaw) return false;
    let rawOra = normalizeazaOraUi(s.ora);
    return (s.ziRaw === tagZi || (zi === "Marti" && s.ziRaw === (saptamanaCheie + "_Marți"))) && 
           rawOra === oraNorm && 
           Number(s.slotIndex) === Number(slotIdx);
  });
  let rowNum = slotExistent ? slotExistent.row : null;

  if (slotExistent) {
    slotExistent.clienta = numeExact;
    slotExistent.antrenament = antrenament;
    slotExistent.bifat = true;
    try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}
  }

  // Totul se actualizează pe loc (eticheta orei, „Bifează toți clienții”, cifrele zilei), nu abia când răspunde baza:
  // altfel schimbarea apărea cu întârziere și părea că apăsările repetate mai bifează o dată
  if (slotExistent) randeazaOrarInstant();
  let btnSave = document.getElementById('btn_save_' + slotDomKey);
  if (btnSave) btnSave.classList.add('btn-save-check-disabled', 'btn-save-check-bifat', 'bifa-acum');

  callBackend("bifeazaPrezenta", {
    row: rowNum, saptamanaCheie: saptamanaCheie, dataCalendar: dataCalendar, zi: zi, ora: oraNorm, clienta: numeExact, antrenament: antrenament, slotIndex: slotIdx
  }, function() {
    incarcaBazaDateSilencios();
  });
}

function anuleazaSlot(zi, ora, slotIdx) {
  let saptamanaCheie = getSaptamanaCheie();
  let tagZi = saptamanaCheie + "_" + zi;
  let oraNorm = normalizeazaOraUi(ora);
  let slotDomKey = `${oraNorm.replace(':', '')}_${slotIdx}`;


  let elCli = document.getElementById('cli_' + slotDomKey);
  let elAnt = document.getElementById('ant_' + slotDomKey);
  let textIntrodus = elCli ? elCli.value.trim() : "";
  let antrenament = elAnt ? (elAnt.dataset.valoare ?? elAnt.value) : "";

  let slotExistent = (DB.orarSloturi || []).find(s => {
    if (!s || !s.ziRaw) return false;
    let rawOra = normalizeazaOraUi(s.ora);
    return (s.ziRaw === tagZi || (zi === "Marti" && s.ziRaw === (saptamanaCheie + "_Marți"))) && 
           rawOra === oraNorm && 
           Number(s.slotIndex) === Number(slotIdx);
  });

  if (!textIntrodus && !antrenament && (!slotExistent || (!slotExistent.clienta && !slotExistent.antrenament))) {
    return;
  }

  let confirmTitleText = currentLang === 'en' ? "Clear slot" : "Golire slot";
  let confirmDescText = currentLang === 'en' ?
    "Clear this slot? The session will be restored to the client's profile if it was checked, and the entry will be removed from history." : 
    "Golești acest slot? Ședința va fi restituită în fișa clientului dacă a fost bifată, iar intrarea va fi ștearsă din istoric.";

  customConfirm(confirmTitleText, confirmDescText, function() {
    bifariTrimise.forEach(k => { if (k.startsWith(`${saptamanaCheie}|${zi}|${slotDomKey}|`)) bifariTrimise.delete(k); });
    let dataCalendar = getDataCalendaristicaCurenta();
    let elBtnSave = document.getElementById('btn_save_' + slotDomKey);
    let elBtnClear = document.getElementById('btn_clear_' + slotDomKey);

    if (elCli) elCli.value = "";
    seteazaStilSlotOcupat(elCli, false);
    if (elAnt) {
      elAnt.value = "";
      aplicaCuloareAntrenament(elAnt);
    }
    if (elBtnSave) {
      elBtnSave.disabled = true;
      elBtnSave.classList.add('btn-save-check-disabled');
    }
    if (elBtnClear) {
      elBtnClear.disabled = true;
      elBtnClear.classList.add('btn-clear-disabled');
    }

    let rowNum = slotExistent ? slotExistent.row : null;

    if (slotExistent) {
      slotExistent.clienta = "";
      slotExistent.antrenament = "";
      slotExistent.bifat = false;
      try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}
      // Rândul se redesenează pe loc (avatarul redevine cifră), nu abia când răspunde baza
      randeazaOrarInstant();
    }

    showToast(t('toastSlotFreed'));

    callBackend("anuleazaSlot", {
      row: rowNum, saptamanaCheie: saptamanaCheie, dataCalendar: dataCalendar, zi: zi, ora: oraNorm, slotIndex: slotIdx
    }, function() {
      incarcaBazaDateSilencios();
    });
  });
}

// Bifa verde atinsă: anularea prezenței (bifată din greșeală), după confirmare. Clientul rămâne pe loc, nebifat;
// prezența se șterge din istoric și ședința se întoarce în abonament (calea golirii locului, fără golire)
function anuleazaPrezentaSlot(zi, ora, slotIdx) {
  const saptamanaCheie = getSaptamanaCheie();
  const oraNorm = normalizeazaOraUi(ora);
  const slotDomKey = `${oraNorm.replace(':', '')}_${slotIdx}`;
  const tagZi = saptamanaCheie + "_" + zi;
  const slot = (DB.orarSloturi || []).find(s => s && s.ziRaw && (s.ziRaw === tagZi || (zi === "Marti" && s.ziRaw === saptamanaCheie + "_Marți"))
    && normalizeazaOraUi(s.ora) === oraNorm && Number(s.slotIndex) === Number(slotIdx));
  const elCli = document.getElementById('cli_' + slotDomKey);
  const nume = slot ? (slot.clienta || '').trim() : '';
  // Între timp s-a scris alt nume în loc: ✓ e din nou bifarea lui
  if (!slot || !slot.bifat || (elCli && elCli.value.trim().toLowerCase() !== nume.toLowerCase())) return bifeazaPrezentaSlot(zi, ora, slotIdx);
  customConfirm(tr('Anulezi prezența?', 'Undo attendance?'),
    tr(`${nume}: prezența se șterge din istoric și ședința se întoarce în abonament. Locul din orar rămâne rezervat.`,
      `${nume}’s attendance is removed from history and the session goes back to the membership. The spot stays booked.`), () => {
      bifariTrimise.forEach(k => { if (k.startsWith(`${saptamanaCheie}|${zi}|${slotDomKey}|`)) bifariTrimise.delete(k); });
      slot.bifat = false;
      try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch (e) {}
      randeazaOrarInstant();
      showToast(tr('Prezența a fost anulată', 'Attendance undone'));
      callBackend("anuleazaSlot", {
        row: slot.row, saptamanaCheie, dataCalendar: getDataCalendaristicaCurenta(), zi, ora: oraNorm, slotIndex: slotIdx, doarPrezenta: true
      }, () => incarcaBazaDateSilencios());
    });
  document.getElementById('modalBtnConfirm').innerText = tr('Anulează', 'Undo');
}

// X de golire: apare în dreapta câmpului de text cât timp scrii în el (nume client, căutări, liste)
// și îl golește dintr-o atingere; anunță schimbarea ca la ștergerea cu tastatura (evenimentul „input”)
(function initGolireCamp() {
  const SELECTOR = 'input.slot-input:not([readonly]), input[list]:not([readonly]), input[type="search"], input.cautare-client-camp, .incasare-suma input';
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'camp-goleste';
  btn.hidden = true;
  btn.setAttribute('aria-label', 'Golește');
  btn.innerHTML = '<svg viewBox="0 0 24 24"><path d="M7 7l10 10M17 7L7 17"/></svg>';
  document.body.appendChild(btn);
  let camp = null;

  const pozitioneaza = () => {
    if (!camp || !camp.isConnected || !camp.value) { btn.hidden = true; return; }
    const r = camp.getBoundingClientRect();
    // Bula: 26px la câmpurile cu chenar, 20px la cele scrise direct pe card (clientul din Orar și din plată, suma);
    // centrată pe verticală, la 6px de marginea din dreapta a câmpului
    const mic = camp.matches('#tabOrar .slot-input, .incasare-client input, .incasare-suma input');
    const d = mic ? 20 : 26;
    btn.classList.toggle('mic', mic);
    btn.style.top = `${Math.round(r.top + r.height / 2 - d / 2)}px`;
    btn.style.left = `${Math.round(r.right - d - 6)}px`;
    btn.hidden = false;
  };

  document.addEventListener('focusin', e => {
    camp = e.target.matches && e.target.matches(SELECTOR) ? e.target : null;
    pozitioneaza();
  });
  document.addEventListener('focusout', () => {
    setTimeout(() => { if (!document.activeElement || !document.activeElement.matches(SELECTOR)) { camp = null; btn.hidden = true; } }, 0);
  });
  document.addEventListener('input', e => { if (e.target === camp) pozitioneaza(); });
  // capture: și derularea din ferestrele de jos (plată, editare), nu doar a paginii; la fel după ce o fereastră termină de urcat
  document.addEventListener('scroll', () => { if (camp) pozitioneaza(); }, { passive: true, capture: true });
  document.addEventListener('animationend', () => { if (camp) pozitioneaza(); }, true);
  // Fereastra trasă în jos (și revenirea ei) mută câmpul: X-ul îl urmează. Fără capture: fereastra s-a mutat deja
  ['pointermove', 'touchmove'].forEach(ev => document.addEventListener(ev, () => { if (camp && !btn.hidden) pozitioneaza(); }, { passive: true }));
  let cadru = 0;
  const urmareste = () => { if (!camp || btn.hidden) return; pozitioneaza(); cadru = requestAnimationFrame(urmareste); };
  document.addEventListener('transitionrun', () => { cancelAnimationFrame(cadru); urmareste(); });
  ['transitionend', 'transitioncancel'].forEach(ev => document.addEventListener(ev, () => { cancelAnimationFrame(cadru); if (camp) pozitioneaza(); }));
  window.addEventListener('resize', () => { if (camp) pozitioneaza(); });

  // pointerdown + preventDefault: câmpul rămâne selectat, tastatura nu se închide
  btn.addEventListener('pointerdown', e => {
    e.preventDefault();
    if (!camp) return;
    camp.value = '';
    camp.dispatchEvent(new Event('input', { bubbles: true }));
    camp.focus();
    btn.hidden = true;
  });
})();

// La pornire Orarul e tab-ul deschis
document.body.classList.toggle('pe-orar', !!document.querySelector('#tabOrar.active'));
document.body.classList.toggle('stil-nou', !!document.querySelector('#tabOrar.active, #tabProgramari.active, #tabIncasari.active, #tabFisa.active'));

// Ora aleasă după „+”: se adaugă singură, fără încă o apăsare
document.getElementById('inputOraCustom')?.addEventListener('change', e => {
  if (e.target.dataset.adaugaDupaAlegere && e.target.value) {
    delete e.target.dataset.adaugaDupaAlegere;
    adaugaOraCustom();
  }
});

function adaugaOraCustom() {
  let inp = document.getElementById('inputOraCustom');
  let ora = inp ? inp.value.trim() : "";
  if (!ora) {
    // „+” fără oră aleasă: deschide alegerea orei, iar ora se adaugă imediat după ce e aleasă
    let deschis = false;
    if (inp && typeof inp.showPicker === 'function') {
      try { inp.showPicker(); deschis = true; } catch (e) {}
    }
    if (deschis) {
      inp.dataset.adaugaDupaAlegere = '1';
    } else {
      showToast(currentLang === 'en' ? "Enter extra hour!" : "Introdu ora suplimentară!", "error");
    }
    return;
  }
  let saptamanaCheie = getSaptamanaCheie();
  let oraNorm = normalizeazaOraUi(ora.replace('.', ':'));
  let m = oraNorm.match(/^(\d{2}):(\d{2})$/);
  if (!m || Number(m[1]) > 23 || Number(m[2]) > 59) {
    showToast(tr("Ora trebuie scrisă ca 07:30", "Use the format 07:30"), "error");
    return;
  }
  let existaDeja = document.querySelector(`#sloturiContainer .hour-block[data-ora="${oraNorm}"]`);
  if (existaDeja) {
    showToast(tr(`Ora ${oraNorm} există deja`, `${oraNorm} already exists`), "error");
    return;
  }

  const zi = ziCurentaCheie;
  callBackend("adaugaOraCustom", { saptamanaCheie: saptamanaCheie, zi: zi, ora: oraNorm }, function(res) {
    // Ora se adaugă doar în ziua selectată: toast-ul o spune explicit
    const zCfg = getZileConfig().find(z => z.cheie === zi);
    const ziText = zCfg ? `${zCfg.nume}, ${formatZiLuna(zCfg.dataDate)}` : '';
    showToast(tr(`✓ Ora ${res.ora} adăugată pentru ${ziText}`, `✓ ${res.ora} added for ${ziText}`));
    if (inp) inp.value = '';
    // Rândurile noi intră direct în orar, ca ora să se vadă imediat; reîncărcarea completă vine după
    if (Array.isArray(res.randuri)) DB.orarSloturi = (DB.orarSloturi || []).concat(res.randuri);
    if (ziCurentaCheie === zi) {
      randeazaOrarInstant();
      aratOraInOrar(res.ora);
    }
    incarcaBazaDateSilencios();
  });
}

// O oră suplimentară adăugată greșit se poate scoate cât e goală (fără cliente și fără prezențe)
function stergeOraCustom(zi, ora) {
  customConfirm(tr('Ștergi ora suplimentară?', 'Remove the extra hour?'), tr(`Ora ${ora} dispare din această zi.`, `${ora} is removed from this day.`), () => {
    const tagZi = getSaptamanaCheie() + "_" + zi;
    callBackend("stergeOraCustom", { saptamanaCheie: getSaptamanaCheie(), zi: zi, ora: ora }, function(res) {
      if (!res || !res.success) {
        showToast(tr('Ora are deja programări și nu se poate șterge.', 'This hour already has bookings and cannot be removed.'), 'error');
        incarcaBazaDateSilencios();
        return;
      }
      DB.orarSloturi = (DB.orarSloturi || []).filter(s => !(s && (s.ziRaw === tagZi || (zi === "Marti" && s.ziRaw === getSaptamanaCheie() + "_Marți")) && normalizeazaOraUi(s.ora) === ora));
      randeazaOrarInstant();
      // Azi: saltul la ora curentă. În altă zi: la ora de dinaintea celei șterse. Cardul de final se recalculează.
      const inainte = Array.from(document.querySelectorAll('#sloturiContainer .hour-block'))
        .map(b => b.getAttribute('data-ora')).filter(o => o && o < normalizeazaOraUi(ora)).pop();
      const esteAzi = esteSaptamanaActiva() && zi === ["Duminica", "Luni", "Marti", "Miercuri", "Joi", "Vineri", "Sambata"][new Date().getDay()];
      if (ziCurentaCheie === zi && esteAzi) autoScrollLaOraCurenta();
      else if (ziCurentaCheie === zi && inainte) aratOraInOrar(inainte);
      showToast(tr(`Ora ${ora} a fost ștearsă`, `${ora} removed`));
      incarcaBazaDateSilencios();
    });
  });
  document.getElementById('modalBtnConfirm').innerText = tr('Șterge', 'Remove');
}

// „+” / „×” pe loc: ora apăsată rămâne în același loc pe ecran. Cardul de final preia diferența de înălțime,
// ca pagina să rămână la fel de lungă (altfel, jos de tot, browserul ar sări în sus la ștergere)
function redeseneazaOrarPeLoc(ora) {
  const cont = document.getElementById('sloturiContainer');
  const endCard = document.getElementById('endScheduleCard');
  const sel = `.hour-block[data-ora="${ora}"]`;
  const hInainte = cont.offsetHeight;
  const topInainte = cont.querySelector(sel)?.getBoundingClientRect().top;
  randeazaOrarInstant();
  if (endCard && endCard.style.minHeight) {
    endCard.style.minHeight = Math.max(0, parseFloat(endCard.style.minHeight) - (cont.offsetHeight - hInainte)) + 'px';
  }
  const bloc = cont.querySelector(sel);
  if (bloc && topInainte !== undefined) window.scrollBy(0, bloc.getBoundingClientRect().top - topInainte);
}

function adaugaLocSuplimentar(zi, ora) {
  callBackend("adaugaLocSuplimentar", { saptamanaCheie: getSaptamanaCheie(), zi: zi, ora: ora }, function(res) {
    DB.orarSloturi = (DB.orarSloturi || []).concat(res.randuri);
    if (ziCurentaCheie === zi) redeseneazaOrarPeLoc(ora);
    incarcaBazaDateSilencios();
  });
}

function stergeLocSuplimentar(zi, ora, row) {
  customConfirm(tr('Ștergi locul suplimentar?', 'Remove the extra spot?'), tr(`Locul dispare de la ora ${ora}.`, `The spot is removed from ${ora}.`), () => {
    callBackend("stergeLocSuplimentar", { row: row }, function(res) {
      if (!res.success) {
        showToast(tr('Locul are deja o programare și nu se poate șterge.', 'This spot already has a booking and cannot be removed.'), 'error');
        incarcaBazaDateSilencios();
        return;
      }
      DB.orarSloturi = (DB.orarSloturi || []).filter(s => s.row !== row);
      if (ziCurentaCheie === zi) redeseneazaOrarPeLoc(ora);
      incarcaBazaDateSilencios();
    });
  });
  document.getElementById('modalBtnConfirm').innerText = tr('Șterge', 'Remove');
}

// ---- Cifrele de sus, comune (Istoric prezențe, Încasări) ----
// O cifră: valoarea mare, eticheta dedesubt; `scurt` = eticheta pentru ecranele înguste (vezi scurteazaEticheteCifre)
const htmlCifra = (nr, text, culoare, scurt) =>
  `<div class="orar-cifra${culoare ? ' orar-cifra-' + culoare : ''}"><b>${nr}</b><span${scurt ? ` data-scurt="${scurt}"` : ''}>${text}</span></div>`;

// „+12% față de Octombrie”: `acum` față de `inainte` (aceleași zile din luna trecută); verde în creștere, roșu în scădere, „–” fără date
function cifraFataDeLunaTrecuta(acum, inainte, an, luna) {
  const loc = currentLang === 'en' ? 'en-GB' : 'ro-RO';
  const prec = new Date(an, luna - 1, 1);
  const cuMajuscula = s => s.charAt(0).toUpperCase() + s.slice(1);
  const lunaLunga = cuMajuscula(prec.toLocaleDateString(loc, { month: 'long' }));
  const lunaScurt = cuMajuscula(prec.toLocaleDateString(loc, { month: 'short' }).replace(/\.?$/, '.'));
  const dif = inainte ? Math.round((acum - inainte) / inainte * 100) : null;
  return htmlCifra(dif === null ? '–' : `${dif > 0 ? '+' : ''}${dif}%`, `${tr('față de', 'vs')} ${lunaLunga}`,
    dif === null ? '' : dif >= 0 ? 'verde' : 'rosu', `${tr('față de', 'vs')} ${lunaScurt}`);
}

// Etichetele care nu încap trec la forma scurtă (abia după desenare cifrele au lățime)
function scurteazaEticheteCifre(container) {
  container.querySelectorAll('span[data-scurt]').forEach(s => { if (s.scrollWidth > s.clientWidth + 1) s.textContent = s.dataset.scurt; });
}

// ---- Istoric prezențe (Orar): luna aleasă cu ‹ › sau tot istoricul, opțional un client ----
// Sus trei cifre: fără client = prezențe, clienți diferiți, față de luna trecută; cu client = ședințe, ultima prezență, media pe săptămână
let istoricLuna = (() => { const d = new Date(); return { an: d.getFullYear(), luna: d.getMonth() }; })();
let istoricToate = false;

function schimbaLunaIstoric(pas) {
  const d = new Date(istoricLuna.an, istoricLuna.luna + pas, 1);
  istoricLuna = { an: d.getFullYear(), luna: d.getMonth() };
  istoricToate = false;
  filtreazaIstoricOrarInstant();
}

function comutaToateLunileIstoric() {
  istoricToate = !istoricToate;
  filtreazaIstoricOrarInstant();
}

function filtreazaIstoricOrarInstant() {
  const lista = document.getElementById('istoricOrarLista');
  if (!lista) return;
  const camp = document.getElementById('filtruClientaOrar');
  const cauta = camp.value.toLowerCase().trim();
  const loc = currentLang === 'en' ? 'en-GB' : 'ro-RO';
  const numeLuna = (an, luna) => { const s = new Date(an, luna, 1).toLocaleDateString(loc, { month: 'long', year: 'numeric' }); return s.charAt(0).toUpperCase() + s.slice(1); };

  // Toate prezențele cu momentul lor; perioada = luna aleasă (sau tot istoricul); clientul = numele conține textul căutat
  const toate = (DB.prezente || []).filter(p => p && p.data).map(p => ({ p, t: parseazaDataOraRo(p.data, p.ora) })).filter(x => x.t);
  const inLuna = (x, an, luna) => { const d = new Date(x.t); return d.getFullYear() === an && d.getMonth() === luna; };
  const alClientului = x => !cauta || (x.p.clienta || '').toLowerCase().includes(cauta);
  const filtrate = toate.filter(x => alClientului(x) && (istoricToate || inLuna(x, istoricLuna.an, istoricLuna.luna))).sort((a, b) => b.t - a.t);

  document.getElementById('istoricLunaText').textContent = istoricToate ? tr('Toată perioada', 'All time') : numeLuna(istoricLuna.an, istoricLuna.luna);
  // Cu toate lunile alese, eticheta o spune deja: butonul apare doar cu o lună aleasă, ca să revii la toate
  document.getElementById('btnIstoricToate').hidden = istoricToate;
  document.getElementById('btnIstoricToate').textContent = tr('Toată perioada', 'All time');
  camp.placeholder = tr('Caută client', 'Find client');

  // Zilele scurse din perioadă (luna curentă doar până azi), pentru media pe săptămână și comparația cu luna trecută
  const azi = new Date();
  const esteLunaCurenta = istoricLuna.an === azi.getFullYear() && istoricLuna.luna === azi.getMonth();
  const zileLuna = new Date(istoricLuna.an, istoricLuna.luna + 1, 0).getDate();
  const zilePerioada = istoricToate
    ? Math.max(1, Math.ceil((azi - Math.min(...filtrate.map(x => x.t), azi)) / 86400000))
    : (esteLunaCurenta ? azi.getDate() : zileLuna);
  const cifra = htmlCifra;
  let cifre;
  if (cauta) {
    const ultima = toate.filter(alClientului).sort((a, b) => b.t - a.t)[0];
    const zileDeLaUltima = ultima ? Math.floor((new Date(azi).setHours(0, 0, 0, 0) - new Date(ultima.t).setHours(0, 0, 0, 0)) / 86400000) : null;
    // Săptămâna asta, ca pastila de pe Confirmări: programate din ținta lui (doar când căutarea arată un singur client)
    const gasiti = (DB.clienti || []).filter(c => c && c.nume && c.nume.toLowerCase().includes(cauta));
    const rand = gasiti.length === 1 ? randuriConfirmariSaptamana().find(r => r.c && r.c.id === gasiti[0].id) : null;
    const saptamana = rand && rand.tinta
      ? cifra(`${rand.facute}/${rand.tinta}`, tr('săpt. asta', 'this week'), rand.facute >= rand.tinta ? 'verde' : rand.facute ? 'portocaliu' : 'rosu')
      : cifra('–', tr('săpt. asta', 'this week'));
    cifre = cifra(filtrate.length, filtrate.length === 1 ? tr('ședință', 'session') : tr('ședințe', 'sessions'), 'accent')
      + cifra(zileDeLaUltima === null ? '–' : zileDeLaUltima === 0 ? tr('azi', 'today') : zileDeLaUltima,
        zileDeLaUltima === 0 || zileDeLaUltima === null ? tr('ultima oară', 'last time') : zileDeLaUltima === 1 ? tr('zi în urmă', 'day ago') : tr('zile în urmă', 'days ago'))
      + saptamana;
  } else {
    const clienti = new Set(filtrate.map(x => (x.p.clienta || '').trim().toLowerCase())).size;
    let comparatie = cifra(Math.round(filtrate.length / Math.max(1, zilePerioada / 7) * 10) / 10, tr('pe săpt.', 'per week'), 'verde');
    if (!istoricToate) {
      // Aceleași zile din luna trecută (la luna curentă, doar primele zile scurse), ca să nu compar o lună începută cu una întreagă
      const prec = new Date(istoricLuna.an, istoricLuna.luna - 1, 1);
      const nrPrec = toate.filter(x => inLuna(x, prec.getFullYear(), prec.getMonth()) && new Date(x.t).getDate() <= zilePerioada).length;
      comparatie = cifraFataDeLunaTrecuta(filtrate.length, nrPrec, istoricLuna.an, istoricLuna.luna);
    }
    cifre = cifra(filtrate.length, filtrate.length === 1 ? tr('prezență', 'attendance') : tr('prezențe', 'attended'), 'accent')
      + cifra(clienti, clienti === 1 ? tr('client', 'client') : tr('clienți', 'clients'))
      + comparatie;
  }
  document.getElementById('istoricCifre').innerHTML = cifre;
  scurteazaEticheteCifre(document.getElementById('istoricCifre'));

  if (!filtrate.length) {
    lista.innerHTML = `<div class="lista-sticla"><div class="notificari-gol">${t('noPresenceFound')}</div></div>`;
    return;
  }
  // Pe zile: „Joi, 12 noiembrie”, fiecare zi un card de sticlă; rândul ca pe Confirmări (avatarul deschide fișa pe scurt)
  const zile = [];
  filtrate.forEach(x => {
    const cheie = new Date(x.t).toDateString();
    if (!zile.length || zile[zile.length - 1].cheie !== cheie) zile.push({ cheie, t: x.t, randuri: [] });
    zile[zile.length - 1].randuri.push(x.p);
  });
  // Prezențele salvate înainte de actualizeazaAntrenamentPrezenta pot avea „-” deși în orar s-a ales antrenamentul după bifare:
  // pentru ele îl luăm din slotul aceleiași zile, ore și client
  const zileChei = ['Duminica', 'Luni', 'Marti', 'Miercuri', 'Joi', 'Vineri', 'Sambata'];
  const antrenamentDinOrar = p => {
    const d = new Date(parseazaDataOraRo(p.data, p.ora));
    const luni = new Date(d.getFullYear(), d.getMonth(), d.getDate() - ((d.getDay() + 6) % 7));
    const zi = zileChei[d.getDay()];
    const prefix = `W_${isoDinData(luni).replace(/-/g, '_')}_`;
    const s = (DB.orarSloturi || []).find(x => x && x.clienta && (x.ziRaw === prefix + zi || (zi === 'Marti' && x.ziRaw === prefix + 'Marți'))
      && normalizeazaOraUi(x.ora) === normalizeazaOraUi(p.ora || '') && cheieNume(x.clienta) === cheieNume(p.clienta || ''));
    return s && s.antrenament ? s.antrenament : '';
  };
  lista.innerHTML = zile.map(z => {
    const eticheta = new Date(z.t).toLocaleDateString(loc, { weekday: 'long', day: 'numeric', month: 'long' });
    return `<div class="lista-titlu">${eticheta.replace(/(^|\s)(\p{L})/gu, (m, sp, l) => sp + l.toUpperCase())}</div>
      <div class="lista-sticla">${z.randuri.map(p => {
        const c = (DB.clienti || []).find(x => x && x.id === p.client_id) || gasesteClientaValida(p.clienta);
        const ant = traduceValoare(p.antrenament && p.antrenament !== '-' ? p.antrenament : antrenamentDinOrar(p));
        return `<div class="prog-row${c ? ' prog-row-client' : ''}"${c ? ` onclick="arataFisaScurta('${escAttr(c.id)}', null, null, null, 'istoric')"` : ''}>
          <div class="slot-num">${c ? avatarSlotHtml(c) : ''}</div>
          <div class="prog-info">
            <span class="prog-name">${escAttr(p.clienta)}</span>
            <span class="prog-sub">${escAttr(normalizeazaOraUi(p.ora || '') || '–')}</span>
          </div>
          ${ant && ant !== '-' ? `<span class="istoric-ant">${escAttr(ant)}</span>` : ''}
        </div>`;
      }).join('')}</div>`;
  }).join('');
}

function getPillClass(val) {
  if (val === "Confirmata" || val === "Confirmed" || val === "Finalizat") return "pill-confirmata";
  if (val === "In asteptare" || val === "Pending" || val === "În așteptare") return "pill-asteptare";
  if (val === "Absenta" || val === "Absent" || val === "Sărit") return "pill-absenta";
  return "pill-empty";
}

function randeazaProgramariInstant() {
  let actContainer = document.getElementById('progActiveList');
  let holdContainer = document.getElementById('progHoldList');
  // După randare nu mai sunt „în încărcare”: fără padding-ul de 16px, rândurile se aliniază cu antetul (#, Nume...)
  if (actContainer) actContainer.classList.remove('loader');
  if (holdContainer) holdContainer.classList.remove('loader');

  if (actContainer) {
    randuriSaptamana = randuriConfirmariSaptamana();
    const mentionPlaceholder = tr('Mențiune...', 'Mention...');
    const cuTinta = randuriSaptamana.filter(r => r.tinta);
    const complete = cuTinta.filter(r => r.facute >= r.tinta).length;
    const partiale = cuTinta.filter(r => r.facute && r.facute < r.tinta).length, zero = cuTinta.length - complete - partiale;
    const luni = new Date(dataReferintaLuniBaza), duminica = new Date(luni.getTime() + 6 * 86400000);
    const perioada = luni.getMonth() === duminica.getMonth() ? `${luni.getDate()} – ${formatZiLuna(duminica)}` : `${formatZiLuna(luni)} – ${formatZiLuna(duminica)}`;
    const elPerioada = document.getElementById('progPerioada');
    if (elPerioada) elPerioada.textContent = `${tr('Săptămâna', 'Week')} ${perioada}`;
    const elTitlu = document.getElementById('progTitluText');
    if (elTitlu) elTitlu.textContent = tr('Confirmări', 'Check-in');
    // Cifrele săptămânii, ca pe Orar; o apăsare arată doar grupul ales (filtrul doar ascunde rânduri, indicii rămân aceiași)
    const elCifre = document.getElementById('progCifre');
    if (elCifre) {
      elCifre.hidden = !cuTinta.length;
      // Un grup gol nu se poate alege (lista ar rămâne goală); dacă grupul ales s-a golit între timp, filtrul se anulează
      if (filtruConfirmari && !{ zero, partial: partiale, complet: complete }[filtruConfirmari]) filtruConfirmari = null;
      const cifra = (grup, nr, text, culoare) => `<button type="button" class="orar-cifra orar-cifra-${culoare}${filtruConfirmari === grup ? ' activ' : ''}" data-grup="${grup}"${nr ? '' : ' disabled'} onclick="filtreazaConfirmari('${grup}')"><b>${nr}</b><span>${text}</span></button>`;
      elCifre.innerHTML = cifra('zero', zero, zero === 1 ? tr('neprogramat', 'not booked') : tr('neprogramați', 'not booked'), 'rosu')
        + cifra('partial', partiale, tr('parțial', 'partly'), 'portocaliu')
        + cifra('complet', complete, complete === 1 ? tr('complet', 'complete') : tr('compleți', 'complete'), 'verde');
    }
    actContainer.dataset.filtru = filtruConfirmari || '';
    const actHtml = randuriSaptamana.map((r, i) => {
      const cls = !r.tinta ? 'fara' : r.facute >= r.tinta ? 'complet' : r.facute ? 'partial' : 'zero';
      const stare = r.tinta ? `<button type="button" class="prog-saptamana ${cls}" onclick="apasaStareSaptamana(${i})" title="${r.facute >= r.tinta ? tr('Are toate ședințele programate', 'All sessions booked') : tr('Trimite un reminder', 'Send a reminder')}">${r.facute >= r.tinta ? '✓' : r.facute ? '◐' : '○'} ${r.facute}/${r.tinta}</button>` : '';
      const mentiune = r.conf ? r.conf.mentiuni : '';
      // Rândurile vechi, fără client în listă, n-au fișă pe scurt: mențiunea și Hold rămân pe rând
      if (!r.c) return `
        <div class="prog-row" data-grup="${cls}">
          <div class="prog-info">
            <span class="prog-name">${escAttr(r.nume)}</span>
            <textarea rows="1" class="prog-mentiuni-textarea" placeholder="${mentionPlaceholder}" onblur="schimbaMentiuneSaptamana(${i}, this.value)">${escAttr(mentiune)}</textarea>
          </div>
          <button type="button" class="btn-trash-action prog-hold-btn" onclick="mutaInHoldSaptamana(${i})" title="${tr('Pune în pauză', 'Pause')}" aria-label="${tr('Pune în pauză', 'Pause')}">${SVG_PAUZA_HOLD}</button>
        </div>`;
      // Tot rândul deschide fișa pe scurt (ținta, mențiunea, Hold); pastila trimite reminderul
      return `
        <div class="prog-row prog-row-client" data-grup="${cls}" onclick="arataFisaConfirmari(${i}, event)">
          <div class="slot-num">${avatarSlotHtml(r.c)}</div>
          <div class="prog-info">
            <span class="prog-name">${escAttr(r.nume)}</span>
            ${!r.tinta ? `<span class="prog-sub">${escAttr(r.stare || '–')}</span>` : ''}
            ${mentiune ? `<span class="prog-sub prog-mentiune">${escAttr(mentiune)}</span>` : ''}
          </div>
          ${stare}
        </div>`;
    }).join('');
    actContainer.innerHTML = actHtml || `<div class="prog-gol">${t('noRecords')}</div>`;
  }

  if (holdContainer) {
    let holdHtml = '';
    let pausePlaceholder = currentLang === 'en' ? 'Pause reason' : 'Motiv pauză';
    // În Hold motivul pauzei e chiar rostul rândului, deci câmpul rămâne mereu vizibil
    // Rândurile ca la Încasări › De reînnoit: avatar, nume, motivul dedesubt (se scrie direct pe rând), acțiunea ca pastilă
    randuriHold().forEach(item => {
      const c = (DB.clienti || []).find(x => randulClientei(item, x, item.nume)) || { nume: item.nume };
      holdHtml += `
        <div class="prog-row">
          <div class="slot-num">${avatarSlotHtml(c)}</div>
          <div class="prog-info">
            <span class="prog-name">${escAttr(item.nume)}</span>
            <textarea rows="1" class="prog-mentiuni-textarea" placeholder="${pausePlaceholder}" onblur="schimbaMentiune(${item.row}, this.value)">${escAttr(item.mentiuni)}</textarea>
          </div>
          <button type="button" class="istoric-toate hold-revine" onclick="stergeProgramareDefinitiv(${item.row})" title="${tr('Scoate din pauză', 'Resume')}"><svg viewBox="0 0 24 24"><path d="M8 5.5v13l10.5-6.5z"/></svg>${tr('Revine', 'Resume')}</button>
        </div>`;
    });
    // Puși în pauză acum: până se salvează (5 secunde, cu „Anulează”) rândul e doar de citit; după salvare vine din bază
    pauzaIntrare.forEach((c, cheie) => {
      if (randuriHold().some(p => cheieNume(p.nume) === cheie)) { pauzaIntrare.delete(cheie); return; }
      holdHtml += `
        <div class="prog-row">
          <div class="slot-num">${avatarSlotHtml(c)}</div>
          <div class="prog-info"><span class="prog-name">${escAttr(c.nume)}</span></div>
        </div>`;
    });
    // Abonamentele înghețate din fișă apar și ele aici (doar de citit; se reiau din fișă)
    const inghetati = (DB.clienti || []).filter(c => esteInghetat(c) && !randuriHold().some(p => randulClientei(p, c, p.nume)));
    inghetati.forEach(c => {
      holdHtml += `
        <div class="prog-row">
          <div class="slot-num">${avatarSlotHtml(c)}</div>
          <div class="prog-info">
            <span class="prog-name">${escAttr(c.nume)}</span>
            <span class="prog-sub">⏸ ${escAttr(stareAbonamentClienta(c).text)}</span>
          </div>
        </div>`;
    });
    holdContainer.innerHTML = holdHtml || `<div class="prog-gol">${t('noClientsHold')}</div>`;
    const elHoldNr = document.getElementById('progHoldNr');
    const nrHold = randuriHold().length + pauzaIntrare.size + inghetati.length;
    if (elHoldNr) elHoldNr.textContent = nrHold ? `(${nrHold})` : '';
  }
}

// ---- Confirmări pe săptămână (sql/2026-11-07_confirmari_saptamana.sql): lista se face singură din abonamente și orar ----
// Ținta = ședințele pe săptămână setate de antrenor sau, automat, ședințele rămase de la începutul săptămânii împărțite la
// săptămânile rămase până la expirare: cine vine mai des primește apoi o țintă mai mică, cine rămâne în urmă una mai mare.
// Programat = programările clientului din orar în săptămâna curentă (făcute sau încă nu). Aceleași reguli ca reminderele din bază.
let randuriSaptamana = [];
const SVG_PAUZA_HOLD = '<svg class="plan-btn-svg" viewBox="0 0 24 24"><rect x="6" y="4.5" width="4" height="15" rx="1.2"/><rect x="14" y="4.5" width="4" height="15" rx="1.2"/></svg>';

// Grupul arătat de cifrele de sus (zero / partial / complet); null = toți
let filtruConfirmari = null;

function filtreazaConfirmari(grup) {
  filtruConfirmari = filtruConfirmari === grup ? null : grup;
  const lista = document.getElementById('progActiveList');
  if (lista) lista.dataset.filtru = filtruConfirmari || '';
  document.querySelectorAll('#progCifre .orar-cifra').forEach(b => b.classList.toggle('activ', b.dataset.grup === filtruConfirmari));
}

// Fișa pe scurt din Confirmări: aceeași fereastră ca pe Orar, plus ținta pe săptămână, mențiunea și mutarea în Hold.
// Salvările sunt cele de pe rând de până acum (seteazaTintaSaptamana, schimbaMentiuneSaptamana, mutaInHoldSaptamana).
function arataFisaConfirmari(i, e) {
  const r = randuriSaptamana[i];
  if (!r || !r.c || (e && e.target.closest('button'))) return;
  arataFisaScurta(r.c.id);
  const actiuni = document.querySelector('#fisaScurta .fisa-scurta-actiuni');
  if (!actiuni) return;
  // Orele deja programate săptămâna asta (din orar), în ordinea zilelor; ✓ = prezență bifată
  const zileChei = ['Luni', 'Marti', 'Miercuri', 'Joi', 'Vineri', 'Sambata', 'Duminica'];
  const zileNume = currentLang === 'en' ? ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'] : ['Luni', 'Marți', 'Miercuri', 'Joi', 'Vineri', 'Sâmbătă', 'Duminică'];
  const ore = (r.programari || []).map(s => ({ zi: zileChei.indexOf(s.ziRaw.split('_').pop().replace('Marți', 'Marti')), ora: normalizeazaOraUi(s.ora), bifat: s.bifat }))
    .sort((a, b) => a.zi - b.zi || a.ora.localeCompare(b.ora));
  const bloc = document.createElement('div');
  bloc.className = 'fisa-scurta-confirmari';
  bloc.innerHTML = `
    <div class="fisa-scurta-zile">
      <span>${tr('Programat săptămâna asta', 'Booked this week')}</span>
      <div>${ore.length ? ore.map(o => `<em class="${o.bifat ? 'bifat' : ''}">${o.bifat ? '✓ ' : ''}${zileNume[o.zi] || ''} ${o.ora}</em>`).join('') : `<small>${tr('Nicio oră încă', 'No sessions yet')}</small>`}</div>
    </div>
    ${r.tinta ? `<button type="button" class="fisa-scurta-rand" id="btnFisaTinta"><span>${tr('Ședințe pe săptămână', 'Sessions per week')}</span><b>${r.tinta}${r.c.sedinteSaptamana ? '' : ` <small>${tr('automat', 'auto')}</small>`}</b></button>` : ''}
    <textarea rows="2" class="fisa-scurta-mentiune" placeholder="${tr('Mențiune', 'Note')}">${escAttr(r.conf ? r.conf.mentiuni : '')}</textarea>`;
  const camp = bloc.querySelector('textarea');
  // Ultima valoare trimisă: a doua ieșire din câmp nu mai salvează (altfel prima mențiune ar crea două rânduri)
  let salvat = r.conf ? r.conf.mentiuni : '';
  camp.onblur = () => {
    if (camp.value === salvat) return;
    salvat = camp.value;
    schimbaMentiuneSaptamana(i, camp.value);
    randeazaProgramariInstant();
  };
  if (r.tinta) bloc.querySelector('#btnFisaTinta').onclick = () => { inchideFisaScurta(); seteazaTintaSaptamana(i); };
  actiuni.before(bloc);
  actiuni.insertAdjacentHTML('beforeend', `<button type="button" class="fisa-scurta-actiune" id="btnFisaHold">${SVG_PAUZA_HOLD}${tr('Pune în pauză', 'Pause')}</button>`);
  actiuni.querySelector('#btnFisaHold').onclick = () => { inchideFisaScurta(); mutaInHoldSaptamana(i); };
}

// bifate = ședințele făcute deja săptămâna asta (scăzute din `ramase`): se adaugă înapoi, ca ținta să nu scadă în timpul săptămânii
function tintaAutomataSaptamana(c, bifate) {
  const disponibile = c.ramase + bifate;
  const luni = new Date(dataReferintaLuniBaza); luni.setHours(0, 0, 0, 0);
  const exp = parseazaDataOraRo(c.dataExpirare);
  // Abonament fără dată de expirare (pornește la prima ședință): toată valabilitatea lui
  const zile = exp ? Math.round((new Date(exp).setHours(0, 0, 0, 0) - luni) / 86400000) + 1 : (zileValabilitateAbonament(c.tipAbonament) || 30);
  return Math.min(Math.max(1, Math.round(disponibile / Math.max(1, zile / 7))), disponibile, 7);
}

const tintaSaptamanaClient = (c, bifate) => c.sedinteSaptamana ? Math.min(c.sedinteSaptamana, c.ramase + bifate) : tintaAutomataSaptamana(c, bifate);

function randuriConfirmariSaptamana() {
  const prefix = `W_${isoDinData(dataReferintaLuniBaza).replace(/-/g, '_')}_`;
  // Rândurile din confirmari se leagă de client după client_id, iar fără legătură, după nume (randulClientei)
  const inHold = c => pauzaIntrare.has(cheieNume(c.nume)) || randuriHold().some(p => randulClientei(p, c, p.nume));
  const folosite = new Set();
  const randuri = (DB.clienti || []).filter(c => {
    const t = stareAbonamentClienta(c).tip;
    return t !== 'arhivat' && t !== 'inghetat' && !inHold(c);
  }).map(c => {
    // Toate rândurile clientului (pot fi mai multe, rămase din lista de dinainte) devin unul: primul cu mențiune
    const aleLui = (DB.progActive || []).filter(p => randulClientei(p, c, p.nume));
    aleLui.forEach(p => folosite.add(p));
    const s = stareAbonamentClienta(c);
    // Ținta doar la abonamentele active (aceleași reguli ca reminderele din bază); ceilalți apar cu starea abonamentului
    const areTinta = (s.tip === 'activ' || s.tip === 'curand') && c.incluse >= 4 && c.ramase > 0;
    const aleSaptamanii = (DB.orarSloturi || []).filter(x => x.clienta && x.ziRaw.startsWith(prefix) && cheieNume(x.clienta) === cheieNume(c.nume));
    const bifate = aleSaptamanii.filter(x => x.bifat).length;
    return {
      c, nume: c.nume, bifate, tinta: areTinta ? tintaSaptamanaClient(c, bifate) : 0, stare: areTinta ? '' : s.text,
      facute: aleSaptamanii.length, programari: aleSaptamanii,
      conf: aleLui.find(p => p.mentiuni) || aleLui[0] || null
    };
  });
  // Rândurile vechi, adăugate de mână pentru nume care nu mai sunt în lista de clienți, rămân cu mențiunile lor
  (DB.progActive || []).forEach(p => {
    // Doar rândurile care nu sunt ale niciunui client din listă (și nici ale unuia arhivat, înghețat sau în Hold)
    if (folosite.has(p) || pauzaIntrare.has(cheieNume(p.nume)) || (DB.clienti || []).some(c => randulClientei(p, c, p.nume))) return;
    randuri.push({ c: null, nume: p.nume, tinta: 0, stare: '', facute: 0, conf: p });
  });
  // Întâi cine n-a programat nimic, apoi cine e la jumătate, apoi cei compleți
  const ordine = r => !r.tinta ? 3 : r.facute >= r.tinta ? 2 : r.facute ? 1 : 0;
  return randuri.sort((a, b) => ordine(a) - ordine(b) || a.nume.localeCompare(b.nume));
}

function apasaStareSaptamana(i) {
  const r = randuriSaptamana[i];
  if (!r || !r.c) return;
  if (r.facute >= r.tinta) return showToast(tr(`${r.nume} are toate ședințele săptămânii programate.`, `${r.nume} has all of this week’s sessions booked.`));
  const prenume = r.c.nume.trim().split(/\s+/)[0], lipsa = r.tinta - r.facute;
  trimiteMesajClient(r.c, r.facute
    ? tr(`Bună, ${prenume}! Săptămâna asta ai programată ${r.facute === 1 ? 'o ședință' : `${r.facute} ședințe`} din ${r.tinta}. Îți rezervi ${lipsa === 1 ? 'și ora care lipsește' : 'și orele care lipsesc'}?`,
      `Hi ${prenume}! This week you have ${r.facute} of ${r.tinta} sessions booked. Shall we book the ${lipsa === 1 ? 'missing one' : 'missing ones'}?`)
    : tr(`Bună, ${prenume}! Încă nu ți-ai programat ședințele săptămâna asta (${r.tinta}). Ce ore îți convin?`,
      `Hi ${prenume}! You haven’t booked this week’s sessions yet (${r.tinta}). Which times suit you?`),
    r.c.contConectat ? URL_APLICATIE : undefined);
}

// Ședințele pe săptămână ale clientului; gol = calculul din abonament
function seteazaTintaSaptamana(i) {
  const r = randuriSaptamana[i];
  if (!r || !r.c) return;
  const auto = tintaAutomataSaptamana(r.c, r.bifate);
  customConfirm(tr('Ședințe pe săptămână', 'Sessions per week'),
    tr(`Câte ședințe trebuie să programeze ${r.nume} pe săptămână (1–7). Lasă gol pentru calculul automat (ședințele rămase pe săptămânile până la expirare): acum ${auto}.`,
      `How many sessions ${r.nume} should book each week (1–7). Leave empty for the automatic count (sessions left over the weeks until expiry): now ${auto}.`), async valoare => {
      const v = valoare === '' ? null : parseInt(valoare, 10);
      if (v !== null && !(v >= 1 && v <= 7)) return showToast(tr('Alege între 1 și 7.', 'Pick between 1 and 7.'), 'error');
      const { error } = await supabaseClient.from('cliente').update({ sedinte_saptamana: v }).eq('id', r.c.id).eq('user_id', utilizatorCurent.id);
      if (error) return showToast(tr('Nu s-a putut salva. Verifică internetul.', 'Could not save. Check your internet.'), 'error');
      r.c.sedinteSaptamana = v;
      try { localStorage.setItem('BFIT_DB_LOCAL', JSON.stringify(DB)); } catch (e) {}
      showToast(tr('✓ Salvat', '✓ Saved'));
      randeazaProgramariInstant();
    }, { valoare: r.c.sedinteSaptamana ? String(r.c.sedinteSaptamana) : '', placeholder: String(auto) });
}

// Mențiunile și Hold-ul stau în confirmari; rândul se creează la prima mențiune sau la mutarea în Hold
function schimbaMentiuneSaptamana(i, val) {
  const r = randuriSaptamana[i];
  if (!r) return;
  if (r.conf) { if (val !== r.conf.mentiuni) schimbaMentiune(r.conf.row, val); return; }
  if (!val.trim()) return;
  callBackend("adaugaRandProgramare", { nume: r.nume, prezenta: "", mentiuni: val, esteHold: false }, () => incarcaBazaDateSilencios());
}

// Pune în pauză: fără întrebare (se poate anula), ca „Revine”. Clientul trece pe loc în „În pauză”, iar salvarea se face
// după 5 secunde, cât toastul oferă „Anulează”. Închisă aplicația în cele 5 secunde, clientul rămâne în lista săptămânii.
const pauzaIntrare = new Map(); // cheieNume → client (sau { nume }) pus în pauză acum

function mutaInHoldSaptamana(i) {
  const r = randuriSaptamana[i];
  if (!r) return;
  const cheie = cheieNume(r.nume);
  if (pauzaIntrare.has(cheie)) return;
  pauzaIntrare.set(cheie, r.c || { nume: r.nume });
  randeazaProgramariInstant();
  let gata = false;
  const timer = setTimeout(() => {
    gata = true;
    // Eroare: clientul revine în lista săptămânii; după salvare rămâne în „În pauză” până vine rândul din bază
    const eroare = () => { pauzaIntrare.delete(cheie); randeazaProgramariInstant(); };
    if (r.conf) callBackend("mutaInHold", { row: r.conf.row }, () => incarcaBazaDateSilencios(), eroare);
    else callBackend("adaugaRandProgramare", { nume: r.nume, prezenta: "", mentiuni: "", esteHold: true }, () => incarcaBazaDateSilencios(), eroare);
  }, 5000);
  const prenume = r.nume.trim().split(/\s+/)[0];
  showToast(tr(`${prenume} e în pauză`, `${prenume} is paused`), 'success', [
    { text: tr('Anulează', 'Undo'), fn: () => { if (gata) return; clearTimeout(timer); pauzaIntrare.delete(cheie); randeazaProgramariInstant(); } }
  ], 5000);
}

function schimbaPrezenta(row, selectEl) {
  let val = selectEl.value;
  selectEl.className = "pill-select " + getPillClass(val);
  actualizeazaProgramareLocal(row, 'prezenta', val);
  callBackend("actualizeazaCampProgramare", { row: row, col: 3, val: val }, function() {
    showToast(currentLang === 'en' ? "✓ Status updated!" : "✓ Status actualizat!");
  });
}

// Memoria și cache-ul local rămân la zi, ca o re-randare (ex. schimbarea limbii) să nu readucă valoarea veche
function actualizeazaProgramareLocal(row, camp, val) {
  let item = (DB.progActive || []).concat(DB.progHold || []).find(p => p.row === row);
  if (!item) return;
  item[camp] = val;
  try { localStorage.setItem("BFIT_DB_LOCAL", JSON.stringify(DB)); } catch(e) {}
}

function schimbaMentiune(row, val) {
  actualizeazaProgramareLocal(row, 'mentiuni', val);
  callBackend("actualizeazaCampProgramare", { row: row, col: 4, val: val }, function() {});
}

// Hold › „Revine”: fără întrebare (se poate anula). Rândul dispare pe loc, clientul apare în lista săptămânii, iar ștergerea
// din bază se face după 5 secunde, cât toastul oferă „Anulează” (revine exact cum era, cu motivul pauzei) și „Programează”
// (Orar, cu căutarea pe numele lui). Închisă aplicația în cele 5 secunde, clientul rămâne în Hold.
const holdIesire = new Set();
const randuriHold = () => (DB.progHold || []).filter(p => !holdIesire.has(p.row));

function stergeProgramareDefinitiv(row) {
  const r = (DB.progHold || []).find(p => p.row === row);
  if (!r || holdIesire.has(row)) return;
  holdIesire.add(row);
  randeazaProgramariInstant();
  let gata = false;
  const sterge = () => {
    if (gata) return;
    gata = true;
    clearTimeout(timer);
    callBackend("stergeRandProgramare", { row: row }, () => {
      DB.progHold = (DB.progHold || []).filter(p => p.row !== row);
      holdIesire.delete(row);
      incarcaBazaDateSilencios();
    }, () => { holdIesire.delete(row); randeazaProgramariInstant(); }); // eroare: rândul rămâne în Hold
  };
  const timer = setTimeout(sterge, 5000);
  const prenume = r.nume.trim().split(/\s+/)[0]; // scurt, ca toastul cu două butoane să încapă și pe 360px
  showToast(tr(`${prenume} a revenit`, `${prenume} is back`), 'success', [
    { text: tr('Anulează', 'Undo'), fn: () => { gata = true; clearTimeout(timer); holdIesire.delete(row); randeazaProgramariInstant(); } },
    { text: tr('Programează', 'Book'), fn: () => {
      sterge();
      comutaTab('tabOrar', tr('Orar', 'Schedule'), document.getElementById('navBtnOrar'), 'orar', 0);
      deschideCautareClient();
      const camp = document.querySelector('.cautare-client-camp');
      camp.value = r.nume;
      camp.dispatchEvent(new Event('input'));
    } }
  ], 5000);
}

function afiseazaFisaClientaInstant() {
  let sel = document.getElementById('selectClientaFisa');
  let container = document.getElementById('detaliiFisa');
  let emptyState = document.getElementById('fisaEmptyState');
  if (!sel || !container) return;
  let nume = sel.value.trim();

  let client = nume ? (DB.clienti || []).find(c => c && c.nume.toLowerCase() === nume.toLowerCase()) : null;
  if (!client) {
    container.style.display = 'none';
    marcheazaFisaDeschisa(false);
    randeazaListaClienteFisa();
    return;
  }

  if (emptyState) emptyState.style.display = 'none';
  document.getElementById('listaClienteFisa').hidden = true;
  // Alt client: secțiunile cu săgeată pornesc închise, istoricul pe tot istoricul (la reîmprospătarea aceluiași client rămân cum erau)
  if (container.dataset.client !== client.id) {
    container.dataset.client = client.id;
    container.querySelectorAll('details.fisa-sectiune').forEach(d => { d.open = false; });
    istoricFisaToate = true;
    progresParti = null;
    nutritieEditorDeschis = false;
    nutritieZiAleasa = null;
  }
  container.style.display = 'block';
  marcheazaFisaDeschisa(true);
  randeazaAntetFisa(client);
  randeazaNotaClient(client);

  document.getElementById('fisaSedinteRamase').innerText = client.ramase;
  // Abonament activat fără dată: valabilitatea pornește la prima ședință bifată
  const asteaptaStart = client.incluse > 0 && (!client.dataExpirare || client.dataExpirare === '-');
  // Înghețat: expirarea e oprită până la Reia (cea de dinainte stă în client.inghetare)
  document.getElementById('fisaValabilitate').innerText = esteInghetat(client) ? tr('În pauză', 'Paused')
    : asteaptaStart ? tr('La prima ședință', 'At first session') : client.dataExpirare;
  
  let progresText = currentLang === 'en' ? `Progress: ${client.efectuate} of ${client.incluse} sessions` : `Progres: ${client.efectuate} din ${client.incluse} ședințe`;
  document.getElementById('fisaProgres').innerText = `${client.efectuate} ${currentLang === 'en' ? 'of' : 'din'} ${client.incluse}`;

  let procent = client.incluse > 0 ? Math.round((client.efectuate / client.incluse) * 100) : 0;
  if (procent > 100) procent = 100;
  document.getElementById('graficBara').style.width = procent + '%';
  document.getElementById('graficProcent').innerText = procent + '%';
  document.getElementById('graficProgresText').innerText = progresText;
  // Inelul: cât a mai rămas din abonament (plin = toate ședințele rămase), cu numărul lor în mijloc
  const areSedinte = client.incluse > 0;
  document.getElementById('fisaInelAbonament').innerHTML = htmlInelProgres(areSedinte ? Math.max(0, client.ramase) / client.incluse * 100 : 0, areSedinte ? client.ramase : '–');
  document.getElementById('fisaAbonamentRamase').innerText = areSedinte
    ? tr(`${client.ramase} din ${client.incluse} ședințe rămase`, `${client.ramase} of ${client.incluse} sessions left`) : tr('Apasă ca să activezi unul', 'Tap to activate one');
  document.getElementById('fisaTipAbonamentAfisat').innerText = areSedinte ? traduceValoare(client.tipAbonament) : tr('Fără abonament', 'No subscription');
  document.getElementById('fisaValabilitate').parentElement.hidden = !areSedinte;

  // Aceeași stare ca în lista de clienți (după dată și ședințe), nu doar câmpul `status` salvat
  let badge = document.getElementById('fisaStatusBadge');
  let stLower = (client.status || '').toLowerCase();
  const stare = stareAbonamentClienta(client);
  document.getElementById('fisaInelAbonament').className = `inel-${stare.tip}`;
  randeazaAcumFisa(client, stare);
  randeazaTileFisa(client);
  randeazaProgramariFisa(client);
  // Îngheață / Reia: doar cât există un abonament propriu-zis în desfășurare (sau deja înghețat)
  const btnIngh = document.getElementById('btnInghetareAbonament');
  if (btnIngh) {
    const poate = stare.tip === 'inghetat' || (['activ', 'curand'].includes(stare.tip) && regulaAbonament(client.tipAbonament).fel === 'abonament');
    document.getElementById('blocInghetareAbonament').hidden = !poate;
    btnIngh.innerText = stare.tip === 'inghetat' ? tr('Reia abonamentul', 'Resume subscription') : tr('Îngheață abonamentul', 'Freeze subscription');
    document.getElementById('notaInghetareAbonament').innerText = stare.tip === 'inghetat'
      ? tr(`${stare.text}. Zilele de pauză se adaugă la expirare când îl reiei.`, `${stare.text}. The paused days are added to the expiry when you resume.`)
      : tr('Pentru concediu sau boală: zilele se opresc, ședințele rămân.', 'For holidays or illness: the days stop, the sessions stay.');
  }
  // Starea, cu aceeași pastilă ca în lista de clienți („Expiră în 3 zile”, „1 ședință”, „Expirat”…); fără abonament o spune deja titlul
  badge.innerHTML = stare.tip === 'nou' ? '' : `<span class="lista-stare ${stare.tip}">${escAttr(stare.tip === 'activ' ? tr('Activ', 'Active') : stare.text)}</span>`;

  document.getElementById('btnStergeClientDefinitivText').innerText = tr('Șterge definitiv', 'Delete permanently');
  let btnArch = document.getElementById('btnArhivareToggle');
  if (btnArch) {
    if (stLower === 'arhivat' || stLower === 'archived') {
      document.getElementById('btnArhivareToggleText').innerText = t('reactivateBtn');
      btnArch.querySelector('svg').innerHTML = '<path d="M3 12a9 9 0 0 1 15-6.7L21 8"/><path d="M21 3v5h-5"/><path d="M21 12a9 9 0 0 1-15 6.7L3 16"/><path d="M3 21v-5h5"/>';
      btnArch.style.color = '#15803d';
    } else {
      document.getElementById('btnArhivareToggleText').innerText = t('archiveBtn');
      btnArch.querySelector('svg').innerHTML = '<rect x="2" y="3" width="20" height="5" rx="1"/><path d="M4 8v11a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8M10 12h4"/>';
      btnArch.style.color = '';
    }
  }

  document.getElementById('editNume').value = client.nume;
  seteazaTipAbonamentSelect(document.getElementById('editTip'), client.tipAbonament);
  document.getElementById('editDataStart').value = dataRoInIso(client.dataStart);
  document.getElementById('editDataExpirare').value = dataRoInIso(client.dataExpirare);
  actualizeazaPastilaData(document.getElementById('editDataStart'));
  actualizeazaPastilaData(document.getElementById('editDataExpirare'));
  document.getElementById('editIncluse').value = client.incluse;
  document.getElementById('editEfectuate').value = client.efectuate;
  document.getElementById('editRamase').value = client.ramase;
  document.getElementById('editStatus').value = client.status;
  document.getElementById('editTelefon').value = client.telefon || '';
  // Emailul = cel al invitației; cu cont conectat e emailul contului, deci blocat
  const elEmail = document.getElementById('editEmail');
  elEmail.value = client.emailInvitatie || '';
  elEmail.disabled = client.contConectat;
  document.getElementById('labelEditEmail').innerText = client.contConectat ? tr('Email (cont)', 'Email (account)') : 'Email';
  actualizeazaContactFisa(client);
  valoriInitialeFisa = valoriEditareFisa();

  actualizeazaBlocContClienta(client);
  const detInscriere = document.getElementById('detailsFisaInscriere');
  detInscriere.hidden = false;
  randeazaFisaInscriereDeschisa();
  randeazaPlanFisa(client);
  // Progresul apare la toți: check-in-urile pot fi și importate (ex. din Google Forms), fără cont sau fișă de obiective
  document.getElementById('detailsProgresClienta').hidden = false;
  // Alt client: progresul se încarcă de la deschiderea fișei (închis), ca Progres să se deschidă instant, cu datele gata.
  // La reîmprospătarea aceluiași client se reîncarcă doar dacă e deschis.
  incarcaProgresFisa(document.getElementById('progresFisaContinut').dataset.client !== client.id);
  incarcaObiceiuriFisa();
  filtreazaIstoricFisaInstant();
}

// Planurile clientului în fișă (cel mai recent primul): progres pe exerciții, ultima notiță, deschidere pentru editare
function randeazaPlanFisa(client) {
  const cont = document.getElementById('planFisaContinut');
  if (!cont) return;
  const planuri = (DB.planuri || []).filter(p => randulClientei(p, client, p.clienta))
    .sort((a, b) => String(b.updated_at || '').localeCompare(String(a.updated_at || '')));
  if (!planuri.length) {
    cont.innerHTML = `<div class="plan-picker-empty">${tr('Niciun plan încă.', 'No plan yet.')}</div>`;
    return;
  }
  cont.innerHTML = planuri.map((p, i) => {
    const ex = (p.continut_json?.sesiuni || []).flatMap(s => (s.exercitii || []).filter(x => (x.exercitiu || '').trim()));
    const facute = ex.filter(x => x.status === 'Finalizat').length;
    const note = (p.continut_json?.sesiuni || []).flatMap(s => [s.nota_client, ...(s.exercitii || []).map(x => x.nota_client)]).filter(n => (n || '').trim());
    const data = p.updated_at ? new Date(p.updated_at).toLocaleDateString(currentLang === 'en' ? 'en-GB' : 'ro-RO') : '';
    return `<button type="button" class="plan-zi-card" onclick="deschidePlanDinFisa('${escAttr(p.id)}')">
      <span class="plan-zi-card-text">
        <span class="plan-zi-card-titlu">${i === 0 ? '' : `<span class="plan-fisa-vechi">${tr('Anterior', 'Earlier')} · </span>`}${escAttr(p.titlu)}</span>
        <span class="plan-zi-card-detalii">${data ? `${tr('Actualizat', 'Updated')} ${data} · ` : ''}${facute}/${ex.length} ${tr('exerciții făcute', 'exercises done')}${note.length ? ` · ${note.length} ${note.length === 1 ? tr('notiță', 'note') : tr('notițe', 'notes')}` : ''}</span>
      </span>
      <svg class="plan-btn-svg plan-zi-card-sageata" viewBox="0 0 24 24"><path d="M9 18l6-6-6-6"/></svg>
    </button>`;
  }).join('');
}

// Deschide planul clientului în Plan de antrenament (cu revenire în fișă la Înapoi)
let planDeschisDinFisa = false;
async function deschidePlanDinFisa(idPlan) {
  await deschideSectiunePlanAntrenamentDinMeniu();
  planDeschisDinFisa = true;
  selecteazaPlanDinLista(idPlan);
}

// Fișă › „Adaugă plan de antrenament”: biblioteca se deschide pentru client; planul ales (gol, șablon, Ale mele)
// devine o copie a clientului, salvată la Salvează
let planNouPentruClient = '';
function adaugaPlanDinFisa() {
  const client = clientaFisaCurenta();
  if (!client) return;
  dupaConfirmareModificariPlan(() => {
    planActiv = construiesteSablonPlanDefault();
    retinePlanInitial();
    deschideSectiunePlanAntrenamentDinMeniu(client.nume);
  });
}

// Orar › fișa pe scurt › „Adaugă antrenament”: biblioteca pentru client, pe Antrenamente, filtrată pe tipul din slot
// (Picioare / Fesieri → Lower body, Spate / Umeri / Piept → Upper body...). Fără potriviri, filtrul revine singur la „Toate”.
function adaugaAntrenamentPentru(client, tipSlot) {
  const t = cheieNume(tipSlot);
  const tip = /picioar|fes|leg|glute/.test(t) ? 'lower'
    : /spate|brat|umer|piept|back|arm|shoulder|chest/.test(t) ? 'upper'
    : /full/.test(t) ? 'full'
    : /cardio|abdom|core/.test(t) ? 'core' : '';
  dupaConfirmareModificariPlan(() => {
    filtruBiblioteca = { text: '', tab: 'antrenamente', filtru: tip ? 'tip:' + tip : 'toate' };
    planActiv = construiesteSablonPlanDefault();
    retinePlanInitial();
    deschideSectiunePlanAntrenamentDinMeniu(client.nume);
  });
}

function actualizeazaBlocContClienta(client) {
  const inp = document.getElementById('fisaEmailInvitatie');
  const stare = document.getElementById('fisaContStatus');
  const btn = document.getElementById('btnInvitaClienta');
  if (!inp || !stare || !btn) return;
  inp.value = client.emailInvitatie || '';
  inp.disabled = client.contConectat;
  // Cu cont conectat emailul e deja în contact, sus: rămâne doar starea
  document.getElementById('fisaContInvitatie').hidden = client.contConectat;
  // Venită din formular: emailul e pus din formular, nu dintr-o invitație trimisă, deci încă „Fără cont”
  const invitata = client.emailInvitatie && !client.fisaInscriere;
  btn.innerText = invitata ? tr('Retrimite invitația', 'Resend invitation') : tr('Trimite invitația', 'Send invitation');
  stare.innerText = client.contConectat
    ? '✓ ' + tr('Conectat', 'Linked')
    : (invitata ? tr('Așteaptă conectarea', 'Waiting to sign in') : tr('Fără cont', 'No account'));
  stare.className = 'fisa-cont-stare ' + (client.contConectat ? 'conectat' : invitata ? 'asteapta' : 'fara');
}

